INSERT INTO campus_documents(collection,id,body) VALUES('sources','e04862b86ac1382a000398b37064a885','{"_id":"e04862b86ac1382a000398b37064a885","key":"ciscn-announcement","name":"全国大学生信息安全竞赛 · 通知公告","type":"html_list","siteUrl":"http://www.ciscn.cn/","entryUrl":"http://www.ciscn.cn/index.php/announcement","updatedAt":"2026-10-15T09:05:33.490Z"}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626ac13e2900039fb4777a8976','{"_id":"1233ab626ac13e2900039fb4777a8976","sourceId":"e04862b86ac1382a000398b37064a885","sourceName":"全国大学生信息安全竞赛 · 通知公告","canonicalUrl":"http://www.ciscn.cn/index.php/announcement/view/422","originalUrl":"http://www.ciscn.cn/index.php/announcement/view/422","title":"全国大学生信息安全竞赛官方网站","contentText":"8月29日至30日，第十九届全国大学生信息安全竞赛（创新实践能力赛）总决赛在齐鲁工业大学（山东省科学院）顺利举行。来自全国各大分区赛的优秀参赛队伍齐聚校（院），同台竞技、交流互鉴，集中展现大学生网络空间安全专业素养和创新实践能力。本届全国总决赛由教育部高等学校网络空间安全专业教学指导委员会主办，齐鲁工业大学（山东省科学院）承办。大赛自启动以来吸引了全国（含香港、澳门特别行政区）804所高校的4150支队伍、逾万名学子参与。经过全国线上初赛和全国六大赛区层层选拔，最终遴选出80支优秀队伍入围全国总决赛。自6月20日教育部高等学校网络空间安全专业教学指导委员会组织承办单位申报答辩以来，齐鲁工业大学（山东省科学院）组建成立工作专班，加强内部统筹和对外协同联动，扎实推进赛事场地落实、技术支撑平台建设、比赛环境搭建、专家沟通联络及经费协调等服务保障工作，历时两个月，高效高标准完成了各项前期准备工作。8月29日上午，总决赛开幕式正式在齐鲁工业大学艺体中心举行。教育部高等学校网络空间安全专业教学指导委员会秘书长、北京电子科技学院教授封化民，济南市委网信办副主任韩霞、齐鲁工业大学（山东省科学院）校长（院长）段培永、计算学部主任吴晓明，参赛队伍指导教师，部分企业嘉宾，以及参赛选手等500余人参加开幕式。计算学部副主任、网络安全学院院长马宾主持开幕式。封化民在开幕式致辞中向出席开幕式的各位领导专家、参赛师生表示热烈欢迎，并向精心筹备本届赛事的齐鲁工业大学（山东省科学院）以及各支持单位表示诚挚感谢！他回顾竞赛十九年办赛历程，并强调网络空间的竞争，归根结底是人才的竞争，教指委始终致力于推动网络空间安全学科建设与人才培养模式改革。本届总决赛立足实战、突出创新，正是落实国家战略、检验人才培养成效的重要平台。他勉励选手敢打敢拼、以成长为本，并预祝总决赛圆满成功。韩霞在致辞中指出，网络安全是国家安全的重要基石，也是数字城市高质量发展的重要保障。近年来，济南深入贯彻落实网络强国战略，统筹推进网络安全和信息化发展，扎实推动数字济南建设提质增效。济南市委网信办将以此次大赛为契机，进一步深化与高校、科研院所及有关单位的交流合作，持续优化网络安全人才发展环境，积极搭建人才培养、技术交流和成果转化平台。    段培永在致辞中表示，近年来校（院）抢抓科教融汇、产教融合战略机遇，统筹推进教育科技人才一体发展。特别是在网络安全领域，先后成立山东省首个网络空间安全学院，牵头建设山东新一代信息技术高等教育共同体，网络空间安全、计算机科学与技术等相关学科获批博士学位授权点。同时，依托国家超级计算济南中心等高能级平台，开设了网络与系统安全、信息内容安全与隐私保护、新兴信息技术安全等三个专业方向，并建设了覆盖攻防对抗、数据安全、人工智能安全等多维度的实验教学体系。校（院）将与兄弟院校携手，不断加强网络空间安全学科专业建设，努力培养更多网络信息安全领域高素质人才，为网络强国建设贡献力量。    开幕式举行了大赛启动仪式。封化民，韩霞、段培永、吴晓明共同点亮启动装置，正式拉开总决赛帷幕。裁判长、华中科技大学教授韩兰胜宣读比赛规则并代表裁判团宣誓，参赛选手罗志文代表参赛选手宣誓。总决赛由Build（知识库构建与安全检测项创新设计，占5%）和 Break&Fix（攻击、防御综合对抗占总分95%）两个环节组成。Build环节于8月12日至17日以线上比赛形式进行。Break&Fix（攻击、防御综合对抗）环节于29日、30日进行现场线下赛，分为CTF解题赛+综合渗透赛，CTF解题赛+AWDP攻防赛，高度还原真实企业网络攻防场景，全方位考核参赛队伍漏洞挖掘、内网渗透、靶机加固、团队协作与实时策略研判能力。总决赛线下赛期间，赛场实行无线网络信号和互联网信号屏蔽，参赛选手在组委会搭建的网络竞赛平台内进行比赛。每日比赛开始后，连续6-8个小时，全程不中断，午餐时段，志愿者送餐至比赛桌面，参赛队员边用餐边比赛。比赛现场大屏幕实时播报竞赛态势和各赛队成绩，裁判全程监督并及时处置各类突发情况。整个赛场气氛紧张热烈，各参赛队伍密切协作、全神贯注，圆满地完成了各项比赛任务。此次总决赛首次由鹏城靶场作为技术支撑平台，全程保障了各赛项稳定、公平地运行。鹏城靶场是网络空间安全领域的大型科学装置，也是国内首个五方角色齐全、覆盖全国28个省份的联邦靶场，关键技术指标居世界领先水平。本次比赛中，靶场以真实对抗、实时演算的实战环境，为渗透测试、CTF、AWDP、build 等赛项提供了高并发、高可用的技术支撑，实现了“以赛促学、以赛促教、以赛促用”的办赛初衷，是科教融汇、协同育人的重要实践。8月30日下午，大赛同期举办“网络空间安全学科建设和人才培养”论坛，计算学部主任吴晓明主持论坛。论坛邀请了教育部高等学校网络空间安全专业教学指导委员会主任委员、中国工程院院士方滨兴，山东大学副校长王美琴，齐鲁工业大学计算学部副主任、网络安全学院院长马宾作专题报告。参赛队员、指导老师、和行业专家500余人参加了论坛。论坛圆满落幕后，总决赛颁奖典礼在艺体中心大礼堂举行。计算学部党委书记王玉立主持颁奖典礼。封化民秘书长上台致辞，全面总结了第十九届全国大学生信息安全竞赛（创新实践能力赛）的举办情况和赛事成果，充分肯定了大赛在服务国家网络安全战略、深化“以赛育才”、培养网络安全实战型人才方面的重要作用；重点感谢齐鲁工业大学（山东省科学院）及各技术支持单位为赛事成功举办提供的组织、技术和服务保障；同时寄语广大青年网安学子以大赛为新起点，勇担时代使命、锤炼实战本领，为网络强国和网络安全事业发展贡献青春力量。经过两天的激烈角逐，10支队伍获得网络安全挑战创新单项奖，22支队伍获总决赛一等奖、24支队伍获二等奖、22支队伍获三等奖。获一等奖队伍的22位指导教师被授予“优秀指导教师”称号。教育部高等学校网络空间安全专业教学指导委员会主任委员、中国工程院院士方滨兴，教育部高等学校网络空间安全专业教学指导委员会副主任委员、山东大学副校长王美琴，教育部高等学校网络空间安全专业教学指导委员会秘书长、北京电子科技学院教授封化民，山东省委网信办总工程师刘春波，中国信息安全测评中心副处长高松，杭州电子科技大学网安学院副院长、教育部高等学校网络空间安全专业教学指导委员会委员任一支，郑州大学网安学院副院长张大龙，齐鲁工业大学（山东省科学院）党委书记吴衍涛等领导和嘉宾出席闭幕式并为获奖选手和优秀指导教师颁奖。    此次总决赛，齐鲁工业大学（山东省科学院）作为承办单位，鹏城靶场作为技术支撑单位，有力地保障了大赛的顺利进行，得到了组委会的肯定和赞扬，大赛组委会分别授予两家单位优秀组织单位奖、优秀平台支撑奖；同时，授予齐鲁工业大学（山东省科学院）网络空间安全系主任李健突出贡献个人奖。此次承办本届全国总决赛，为校（院）深化与全国高水平院校在网络空间安全领域的交流合作搭建了重要平台，并充分展示了校（院）科教融合办学体制优势和高能级平台基础设施建设实力。校（院）将以此次赛事为契机，进一步深化网络空间安全领域协同交流，厚植学科建设根基，健全创新人才培养体系，为网络强国、教育强国和数字中国建设不断作出新的更大贡献！第十九届全国大学生信息安全竞赛—创新实践能力赛总决赛创新单项奖获奖名单.pdf第十九届全国大学生信息安全竞赛—创新实践能力赛总决赛优秀组织、优秀平台、突出贡献奖.pdf第十九届全国大学生信息安全竞赛—创新实践能力赛总决赛获奖名单.pdf第十九届全国大学生信息安全竞赛—创新实践能力赛总决赛优秀指导教师获奖名单.pdf","category":"competition","status":"published","publishedAt":null,"discoveredAt":"2026-10-03T17:40:57.304Z","createdAt":"2026-10-03T17:40:57.304Z","updatedAt":"2026-10-11T15:45:57.836Z","summary":{"audience":["大学生","参赛队伍指导教师","网络安全领域师生","高校相关单位"],"bullets":["总决赛于8月29日至30日在齐鲁工业大学（山东省科学院）举行，由教育部高等学校网络空间安全专业教学指导委员会主办、齐鲁工业大学承办。","大赛吸引全国（含香港、澳门）804所高校4150支队伍、逾万名学子参与，最终80支队伍入围全国总决赛。","总决赛由Build环节（8月12日至17日线上）和Break&Fix环节（8月29日、30日线下）组成，首次由鹏城靶场作为技术支撑平台。","8月30日下午举办“网络空间安全学科建设和人才培养”论坛，随后举行颁奖典礼，共22支队伍获一等奖、24支获二等奖、22支获三等奖。","大赛组委会授予齐鲁工业大学（山东省科学院）优秀组织单位奖、鹏城靶场优秀平台支撑奖，并授予李健突出贡献个人奖。"],"keyDates":[{"label":"Build环节开始","date":"2025-08-12T00:00:00.000Z","evidence":"Build环节于8月12日至17日以线上比赛形式进行。"},{"label":"Build环节结束","date":"2025-08-17T00:00:00.000Z","evidence":"Build环节于8月12日至17日以线上比赛形式进行。"},{"label":"总决赛开始","date":"2025-08-29T00:00:00.000Z","evidence":"8月29日至30日，第十九届全国大学生信息安全竞赛（创新实践能力赛）总决赛在齐鲁工业大学（山东省科学院）顺利举行。"},{"label":"总决赛结束","date":"2025-08-30T00:00:00.000Z","evidence":"8月29日至30日，第十九届全国大学生信息安全竞赛（创新实践能力赛）总决赛在齐鲁工业大学（山东省科学院）顺利举行。"}],"oneLine":"第十九届全国大学生信息安全竞赛创新实践能力赛总决赛8月29日至30日在齐鲁工业大学举行。","sourceUrl":"http://www.ciscn.cn/index.php/announcement/view/422"},"categories":["competition"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626ac13e2d00039fb84c66948b','{"_id":"1233ab626ac13e2d00039fb84c66948b","sourceId":"1233ab626ac140af0003a85f00e57db2","sourceName":"北京交通大学 · 本科生院通知公告","canonicalUrl":"https://bksy.bjtu.edu.cn/informations/639086467811381609.html","originalUrl":"https://bksy.bjtu.edu.cn/informations/639086467811381609.html","title":"《大学美育实践》课程修习须知 2025-2026-2","contentText":"亲爱的同学们：\n\n  大家好！\n\n《大学美育实践》课程是全校通识素养类课程，面向所有专业（除艺术类）开设，旨在让学生涉猎大艺术（全学科）背景知识，提升不同学科间的交叉、融合与共享，提高大学生科学与艺术知识体系的融通能力。为“新工科”高校的复合型高层次人才打下欣赏艺术、懂得审美、融通交叉、以美立志的重要艺术学基础。为提供丰富、全面的艺术通识学习，课程依托多个教学单位的师资力量，联动社会艺术教育资源，开设了提供不同艺术形式体验、培养不同艺术素养的套餐，分为素养类（艺术场馆套餐、现代设计审美套餐）和实践类（书法临习套餐、音乐实践套餐）两类（套餐数量及选择依据每学期师资安排进行调整），营造“人人皆学、处处能学、时时可学”的高校艺术通识课程的优良生态。\n\n为了更好的进行审美浸润，课程采用小程序注册、选择课程套餐的形式，进行课程进度的推进、打卡资料的上传及结课。下面为本课程的修习细则，请同学们知悉。\n\n \n\n1.修习本课程将产生一定的学习成本，包括观展费用、物料费用等需自理。详情如下：\n\n序号\n\n套餐名称\n\n学习成本提示\n\n用途\n\n1（素养类）\n\n艺术场馆套餐\n\n65-180 元\n\n购买参观门票\n\n2（素养类）\n\n现代设计审美套餐\n\n0元\n\n无\n\n3（实践类）\n\n书法临习套餐\n\n0-40元\n\n购买笔墨纸砚等物料\n\n4（实践类）\n\n音乐鉴赏套餐\n\n0元\n\n无\n\n \n\n2.艺术场馆套餐修习要求：参观打卡5次+期末作业，根据小程序具体时间要求提交各项作业。本学期提供5家场馆打卡地。其中，免费场馆无需扫描前台二维码，收费场馆（UCCA尤伦斯当代艺术中心）需要购买门票后扫描前台二维码。同学们可依据自身兴趣和学习需求，自选场馆参观打卡。\n\n序号\n\n展览\n\n打卡场馆\n\n学生票价\n\n1\n\n中国美术馆 任一展览（需官网提前预约）\n\n中国美术馆\n\n免费\n\n2\n\n北京中轴线：中国理想都城秩序的杰作（需官网提前预约）\n\n正阳门箭楼\n\n免费\n\n3\n\n中国工艺美术馆/中国非物质文化遗产馆 任一展览（需官网提前预约）\n\n中国工艺美术馆/中国非物质文化遗产馆\n\n免费\n\n4\n\n首都博物馆 任一展览（需官网提前预约）\n\n首都博物馆\n\n免费\n\n5\n\nUCCA尤伦斯当代艺术中心任一展览（携带身份证、学生证至前台购票）\n\nUCCA尤伦斯当代艺术中心\n\n交大学生专属票价\n\n特别提示：\n\n（1）各个艺术场馆每周都会有1天闭馆日，同学们出行前请在官网查询闭馆信息，以免跑空。\n\n（2）UCCA尤伦斯当代艺术中心有针对交大学生的专属优惠。同学们可前往现场出示北京交通大学学生证直接购票，享受比官网更优惠的票价。\n\n \n\n3. 每学期的《大学美育实践》课程，在退补选课结束之后的第一天为“大美无域”小程序初始注册日，之前不可注册。注册时，请同学们按照要求注册。注册完成后，请同学们仔细阅读各套餐打卡过程作业提交时间节点，及期末作业提交截至日期。请同学们仔细阅读小程序打卡细则，按要求完成！\n\n（1）本学期的“大美无域”小程序初始注册日为3月12日10:00开始。请扫描二维码注册。\n\n（2）所有打卡任务与最终作业均在小程序上提交。提交时间为：3月12日10:00——5月10日23：59。如遇提交问题，在此时间段内，请与相应套餐负责教师取得联系，直至提交成功。5月10日23：59为小程序系统关闭时间，没有完成作业提交的同学将无法提交作业，课程组不接受以邮件或其他形式补交作业。请务必知悉！\n\n（3）套餐负责人邮箱：\n\n艺术场馆套餐：李兆龑  \n10129@bjtu.edu.cn\n\n现代设计审美套餐：唐然  \n10131@bjtu.edu.cn\n\n书法临习套餐：张澎  1362167209@qq.com\n\n音乐鉴赏套餐：安薇  weian@bjtu.edu.cn\n\n课程负责人：杨梦婉  yangmw@bjtu.edu.cn\n\n \n\n4. 各套餐百分制评分标准如下：\n\n套餐\n\n名称\n\n评分标准\n\n1\n\n艺术场馆套餐\n\n总体标准：基础分值（占总分值的50%）+进阶分值（占总分值的50%）。\n（1）基础分值：5次打卡为基础分值的50%。如打卡按照小程序作业要求，完成质量较高的，基础分最高可获得50分。如没有执行打卡拍摄规范，或撰写心得体会文字查重率高于10%的，为0-30分。\n（2）进阶分值：进阶分值为期末作业，分数占50%。期末作业完成质量较高的，最高可获得50分。如没有执行期末作业要求或论文文字查重率高于10%的，为0-30分。\n评价标准如下：\n①100-90分 内容研究扎实，分析逻辑清晰、合理，所选择使用的图片和影像等素材恰当美观，有自己明确的观点和见解，视角独到，并能以有创意的表达方式进行信息的准确传达；\n②89-80分 内容研究扎实，信息完整充实，有明确的观点并能够以规整的结构组织内容，所选素材恰当，能支撑内容和观点的表述且较为美观，信息表达清晰准确且兼具美感；\n③79-70分 内容信息完整充实，组织结构逻辑合理，所选素材恰当，能支撑内容和观点的表述，有清晰完整的表达；\n④69-60分 信息整理较为完整，还存有可细化的空间；素材的选择较为随意，有待改善；表达逻辑较为通顺，语言清晰流畅，尚需有更为明确的观点和视角；\n⑤59-0分 信息不完全，主要信息有欠缺；结构琐碎，未能形成逻辑合理的结构体系；缺少有效素材的支撑；未能形成准确清晰的信息表达。\n注：打卡拍摄照片必须按照小程序上的任务要求上传，如没有按照要求上传或出现借用他人作品、网络图片等情况的，一律按0分处理。\n\n2\n\n现代设计审美套餐\n\n总体标准：基础分值（占总分值的50%）+进阶分值（占总分值的50%）。\n（1）基础分值：完成小程序发布的线上资源学习打卡、质量较高的，最高可得基础分50分。\n（2）进阶分值：期末论文或视频作业最高可得50分。评价标准如下：\n①50-40分 内容研究扎实，分析逻辑清晰、合理，所选择使用的图片和影像等素材恰当美观，有自己明确的观点和见解，视角独到，并能以有创意的表达方式进行信息的准确传达；\n②39-30分 内容研究扎实，信息完整充实，有明确的观点并能够以规整的结构组织内容，所选素材恰当，能支撑内容和观点的表述且较为美观，信息表达清晰准确且兼具美感；\n③29-20分 内容信息完整充实，组织结构逻辑合理，所选素材恰当，能支撑内容和观点的表述，有清晰完整的表达；\n④19-10分 信息整理较为完整，还存有可细化的空间；素材的选择较为随意，有待改善；表达逻辑较为通顺，语言清晰流畅，尚需有更为明确的观点和视角；\n⑤9-0分 信息不完全，主要信息有欠缺；结构琐碎，未能形成逻辑合理的结构体系；缺少有效素材的支撑；未能形成准确清晰的信息表达。\n\n3\n\n书法临习套餐\n\n总体标准：基础分值（占总分值的50%）+进阶分值（占总分值的50%）。\n（1）书法基础分：按照小程序发布的任务描述按时按量，规范的完成全部书法临习打卡任务和书法临创最终作业即可得到书法基础分满分50分。其中每完成1次书法临习打卡任务得10分，共3次满分30分。完成1次书法临创最终作业得20分，共1次满分20分。\n（2）书法进阶分：在打卡分的基础上，根据书法临习和临创的评分要点，按照以下6个分数段进行进阶分数的评分：\n（1）50-40分\n①临习以及临创作业能够掌握多种字体的书写规律。\n②临习以及临创作业点画分明，用笔精到，线条富有力度，并有融入一定的感情色彩。\n③临习以及临创作业结构安排合理妥当，充满生机和活力，并有相当的个人风格。\n④临创作业章法从正文到落款、铃印等均较为和谐、完整，具有强烈的感染力。\n⑤临创作业没有错字、漏字、繁体字和简化字相混等现象。\n（2）39-30分\n①临习以及临创作业点画遒劲，并应下笔有源，略见毛笔字的功底。\n②临习以及临创作业结构巧妙，在动态中见平衡，疏密关系处理得体。\n③临创作业章法错落有致，主次得体，虚实相生，能够充分运用落款的大小比例、以及印章的位置等，协调作品的布局。\n（3）29-20分\n①临习以及临创作业点画的线条爽朗，用笔精到。\n②临习以及临创作业结构能按照书法结体的法则，讲究字形的造型美观，并且有丰富的变化。\n③临创作业章法能讲究虚实相生，错落变化，落款与正文布局合理，统一、完整。\n（4）19-10分\n①临习以及临创作业点画用笔有轻重之分。\n②临习以及临创作业结构安排能做到合理。\n③临习以及临创作业按照推荐碑帖所示的特点，能够加以正确表现。\n④临创作业能初步协调作品内容与落款位置的关系，整体布局较为统一和完整。\n（5）9-1分\n①临习以及临创作业达不到基本要求。\n②临习以及临创作业点画不够规范。\n③临习以及临创作业字形结构有问题。\n④临创作业有错别字，没有题款。\n（6）0分\n借用他人作品、上传网络图片等。\n\n4\n\n音乐鉴赏实践套餐\n\n总体标准：日常作业共6次，每次作业满分100分，占总分值的10%（10分），合计共占总分值的60%（60分）提交材料符合要求且质量较高的，可获得满分。期末作业共1次，满分100分，占总分值的40%（40分）。按照以下5个分数段进行期末论文的评分：\n（1）90-100分：学生在期末论文中充分展示了对音乐鉴赏美育课程的深刻理解和高水平的学术能力。论文题目明确，结构清晰，学生需提供音乐鉴赏美育课程的历史和背景，明确讨论其对学生的影响和必要性，以及可能的实际应用。论文应该具有原创性，不得抄袭他人作品，语言表达应该准确、流畅。\n（2）80-89分：学生在期末论文中表现出对音乐鉴赏美育课程的基本理解和一定程度的学术能力。论文结构基本清晰，内容涵盖了音乐鉴赏美育课程的主要方面，但可能需要更多的深度和详细信息。\n（3）70-79分：学生在期末论文中表现一般，虽然完成了基本的任务要求，但可能存在内容较为肤浅或不够详细的问题，论文结构可能不够清晰，语言表达可能不够流畅。期末论文需要明显改进，以提高分数和深度。\n（4）60-69分：学生在期末论文中表现不佳，未能充分满足任务要求，内容可能不够详尽，结构混乱，语言表达不流畅。需要重大改进以达到基本要求。\n（5）0-59分：学生在期末论文中未能完成任务要求，未按要求上传、抄袭他人作品、上传网络图文或出现其他严重违规情况。以0分处理。\n\n \n\n祝同学们修习愉快！开启欣赏艺术之美、体验艺术之灵、涵养身心之魂的旅程！\n\n \n\n                                                                  《大学美育实践》课程组\n\n2026年3月","category":"school","status":"published","publishedAt":"2026-03-09T00:00:00.000Z","discoveredAt":"2026-10-03T17:41:01.128Z","createdAt":"2026-10-03T17:41:01.128Z","updatedAt":"2026-10-11T15:46:05.694Z","summary":{"audience":["北京交通大学本科生（除艺术类）"],"bullets":["课程面向所有专业（除艺术类），分素养类与实践类套餐，部分套餐有学习成本。","艺术场馆套餐需参观打卡5次加期末作业，提供5家场馆，其中UCCA需购票扫码。","小程序初始注册日为3月12日10:00，所有打卡与作业提交时间为3月12日10:00至5月10日23:59。","各套餐有详细百分制评分标准，打卡照片须按要求上传，违规按0分处理。","套餐负责人及课程负责人邮箱已列出，提交问题可在规定时间内联系。"],"keyDates":[{"label":"小程序初始注册日","date":"2026-03-12T02:00:00.000Z","evidence":"本学期的“大美无域”小程序初始注册日为3月12日10:00开始。"},{"label":"提交开始时间","date":"2026-03-12T02:00:00.000Z","evidence":"提交时间为：3月12日10:00——5月10日23：59。"},{"label":"提交截止时间","date":"2026-05-10T15:59:00.000Z","evidence":"5月10日23：59为小程序系统关闭时间，没有完成作业提交的同学将无法提交作业。"}],"oneLine":"《大学美育实践》课程修习须知，含套餐成本、打卡要求、注册与提交时间及评分标准。","sourceUrl":"https://bksy.bjtu.edu.cn/informations/639086467811381609.html"},"categories":["school","college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626ac13e2e00039fc015013062','{"_id":"1233ab626ac13e2e00039fc015013062","sourceId":"e04862b86ac1382a000398b37064a885","sourceName":"全国大学生信息安全竞赛 · 通知公告","canonicalUrl":"http://www.ciscn.cn/index.php/announcement/view/418","originalUrl":"http://www.ciscn.cn/index.php/announcement/view/418","title":"一、比赛组织架构","contentText":"为贯彻落实国家网络空间安全发展战略，加快培育兼具渗透攻击、安全防护综合素养的实战型网络安全人才，践行以赛促学、以赛促教、以赛促用核心理念，推动网络安全专业人才培养与产业需求产学研用深度融合，第十九届全国大学生信息安全竞赛-创新实践能力赛全国总决赛将如期在山东省齐鲁工业大学举行。赛事采用CTF解题、综合渗透、AWD Plus静态攻防相结合的综合竞赛模式，高度还原真实企业网络攻防场景，全方位考核参赛队伍漏洞挖掘、内网渗透、靶机加固、团队协作与实时策略研判能力。赛事由高校承办，专业网络安全企业提供竞赛靶场、流量分析等平台技术支撑，赛事面向全国高校在校学生开展选拔，旨在检验高校网络空间安全专业实践教学成效，挖掘优秀青年攻防人才，为政企、安全行业输送复合型实战后备力量。本届赛事由齐鲁工业大学（山东省科学院）承办，鹏城靶场、国家超级计算济南中心提供竞赛靶场搭建、超算算力调度等核心技术支撑，联合专业会展承接单位共同保障赛事场地、组网与后勤服务，共同为参赛选手打造安全、稳定、公平的竞赛环境。一、比赛组织架构比赛名称：全国大学生信息安全竞赛-创新实践能力赛。主办单位：教育部高等学校网络空间安全专业教学指导委员会。承办单位：齐鲁工业大学（山东省科学院）。技术支持单位：鹏城靶场、国家超级计算济南中心、软极网路技术（北京）有限公司、四川亿览态势科技有限公司。二、赛事安排1.比赛时间和地点比赛时间：2026年8月29日—2026年8月30日。比赛地点：齐鲁工业大学长清校区-艺体中心。导航地址：山东省济南市长清区大学路3501号。公共交通路线：济南地铁1号线大学城（B2口）出站——步行515米到达齐鲁工业大学（长清校区）南门/西门。2.参赛对象经过初赛与半决赛后，排名前80的队伍。3.总决赛奖项（1）总决赛成绩排名第1-22名的队伍获得全国一等奖；（2）总决赛成绩排名第23-46名的队伍获得全国二等奖；（3）总决赛成绩排名第47名以后的队伍获得全国三等奖；（4）组委会根据各个分赛项比赛情况评选10-20名队伍授予网络安全挑战创新单项奖。4.赛程安排日期时间环节内容8月12日 至8月17日全天Build环节1.赛题附件包下发，测试。2.选手按照Build环节赛题要求完成入侵溯源分析和攻击图谱构建。3.选手在平台提交结果截止时间为8月17日24时。8月22日10:00-18:00Build环节成绩公布1.公布build环节成绩。8月28日（星期五）14:00-18:00选手报到（齐鲁工业大学长清校区-艺体中心）1.选手前往报到处进行身份验证（须携带本人有效身份证件、学生证及学校出具的在读证明）。2.领取参赛相关资料。3.地点：齐鲁工业大学长清校区-艺体中心。14:00-18:00比赛网络环境测试（齐鲁工业大学长清校区-艺体中心）1.选手签到后可前往比赛场地调试电脑设备，测试网络连通性，18:00后不再开放测试环境。2.选手测试结束后，乘坐摆渡车至酒店休息。8月29日（星期六） 7:30-8:30选手签到（齐鲁工业大学长清校区-艺体中心）1.选手签到，复核身份，收取手机。2.确认比赛网络连通性。8:30-9:00开幕式（齐鲁工业大学长清校区-艺体中心）1.介绍出席领导及嘉宾。2.全体起立奏唱中华人民共和国国歌。3.领导致辞。4.裁判长宣读比赛规则。5.裁判代表宣誓。6.参赛选手代表宣誓。7.宣布比赛开始。9:00-17:00比赛环节（齐鲁工业大学长清校区-艺体中心）1.CTF解题赛+综合渗透赛。2.午餐由组委会统一配送至选手工位，用餐期间比赛正常进行。8月30日（星期日） 7:30-8:00选手签到（齐鲁工业大学长清校区-艺体中心）1.选手签到，复核身份，收取手机。2.确认比赛网络连通性。8:00-14:00比赛环节（齐鲁工业大学长清校区-艺体中心）1.CTF解题赛+AWDP攻防赛。2.午餐由组委会统一配送至选手工位，用餐期间比赛正常进行。14:30-17:30论坛（齐鲁工业大学长清校区-艺体中心大礼堂）1. 网安学科建设与人才培养论坛。2. 颁奖及闭幕仪式。三、比赛方案1.赛制说明本次比赛共采用四种赛题模式，包括Build环节、CTF竞赛、综合渗透、AWDP竞赛模式。其中，线下比赛各环节均按比赛日期独立开放，第一天比赛题目无法在第二天继续解答。（1）Build环节环节名称：基于多源日志的攻击溯源工程。比赛时间：8月12日9:00-8月17日24:00。比赛形式：线上参赛。核心规则：参赛队伍需分析组委会提供的企业多源日志、网络流量及Windows事件记录，识别攻击证据，还原攻击时间线和攻击路径，并按规定格式提交证据集、攻击图及IOC。考核重点：多源数据处理与关联分析、攻击证据发现、攻击阶段判定、复杂攻击路径还原、攻击图谱构建及工程实现能力。积分规则：参赛队伍须在规定时间内将Build成果提交至平台，组委会将对所有提交内容进行审核评分。每队最多提交3次，最终成绩取最高分。分数规划；格式合规10分+证据发现25分+攻击阶段分类10分+时间线还原15分+拓扑节点10分+拓扑边关系20分+IOC提取10分。最终得分：战队得分/规划分值*100分。表1 Build环节考核内容题目类型类型描述多源日志分析与攻击溯源基于模拟企业环境的网络流量、服务器日志、Windows事件日志、应用审计日志和安全告警等多源数据，考察参赛队伍的数据处理、关联分析、攻击证据识别、攻击路径还原及攻击图构建能力，参赛成果按照统一格式提交并由平台自动评分。（2）CTF 竞赛比赛时间：8月29日9:00-17:00，共计8小时；8月30日8:00-14:00，共计6小时。CTF 比赛第一天题目无法在第二天进行解答。参赛队伍通过与在线环境交互或离线分析文件，解决区块链技术、信息隐藏、国产密码、工控技术等方向的安全技术挑战，获取题目预设flag。比赛强调单点技术深度、代码编写与独立漏洞分析能力，侧重选手单项技术功底。参赛队伍独立完成各类安全题目，互不干扰，不存在互相攻击、防守对抗环节，得分仅依靠自主解题获取对应 Flag 分值，无靶机防护、对抗博弈相关操作。参赛队伍拥有独立操作环境，各队伍任务环境完全隔离，无交互对抗逻辑。积分规则：采用动态积分制（每题得分除去题目预设分外，对解出题目的队伍根据结题时间获得奖励分，按总分由高到低排名，同分则以提交时间为准，用时短者优先。最终得分=（当前队伍分数/最高队伍分数）*100分。表2 CTF赛制考核内容题目类型类型描述网络安全该类型包括Web应用架构、二进制程序机制、密码算法原理、杂项数据特征及逆向工程目标的安全特性与潜在风险；能够通过SQL注入、缓冲区溢出、算法缺陷利用、反编译分析等方式构建攻击路径；并结合代码审计、动态调试、密码分析、数据取证、逆向工程等技术，完成Web渗透、权限提升、密码破解、信息提取与程序逻辑还原。区块链技术该类型包括链上运行机制、智能合约安全、DeFi业务逻辑、链上数据分析等内容，重点考察参赛选手对区块结构、交易流程、账户模型、Gas机制、合约调用关系和资产流转路径的理解能力。题目可结合合约审计、漏洞分析、交易追踪、权限校验、签名验证等场景，评价选手发现问题、还原攻击过程、构造验证思路及提出修复建议的综合能力。工控安全该类型包括工业控制系统架构、现场设备通信、工业协议分析、PLC逻辑及生产网络边界防护等内容设置赛题，重点考察参赛选手对OT环境中设备关系、业务流程和通信特征的理解能力。信息隐藏该类型包括围绕图像、音频、视频、文档、压缩包及网络流量等载体中的隐蔽信息提取，重点考察参赛选手对文件结构、编码方式、元数据特征和隐写痕迹的分析能力。（3）综合渗透竞赛比赛时间：8月29日9:00-17:00，共计8个小时（并行）。核心规则：本次综合渗透竞赛采用全流程实战逐层渗透考核模式，定型为线下实操演练竞赛。竞赛搭建内网业务环境，划分互联网区、DMZ 隔离区、内网业务区，还原多层边界防火墙、路由访问控制等真实网络防护架构，部署多类业务靶机。竞赛实行独立环境机制，每支参赛队伍分配一套专属靶场环境，队伍之间环境相互隔离、互不干扰。考核重点：参赛队伍需遵循网络边界访问逻辑，逐层突破区域防护壁垒，综合运用信息收集、漏洞利用、权限提升、内网横向移动等攻防技术，逐级获取各节点靶机权限，搜寻隐藏 Flag 完成全链路渗透通关。积分规则：不同Flag设置差异化分值，队伍总分由成功获取的Flag分值累加得到，比赛中队伍成功获取所有 Flag 对应的分值，最后统计所获取Flag总数，获取相应的分值，如获取的Flag总数相同，则通过提交Flag的时间对比，用时最短者获取相应的激励分：最终得分:（当前队伍分数/最高队伍分数）*100分。表3 综合渗透赛制考核内容题目类型类型描述外网初始突破选手从互联网区开展信息探测、漏洞利用，突破外层边界防护，获得初始立足点与 Flag，实现进入 DMZ 区。内网纵深横向渗透依托外网权限穿透边界，获取内网访问凭证、通道资源，开展权限提升、凭证窃取、内网横向移动，多节点持续拓展权限。区块链专项渗透基于区块链智能合约仿真环境开展渗透，覆盖重入攻击、未授权访问、私钥泄露等典型区块链安全风险。选手通过合约漏洞利用、密钥窃取等方式完成攻击目标，获取专项 Flag，考核区块链应用攻防能力。（4）AWD Plus 模式（静态攻防解题加固赛）比赛时间：8月30日8:00-14:00，共计6小时。核心规则：将企业或院校等真实网络结构抽象为竞赛平台模拟环境，参赛队需同时扮演攻击方与防守方。考核重点：实时挖掘对手环境漏洞并提交flag获取攻击分；修复自身环境漏洞以获得防御分。积分规则：采用周期动态积分制，每个周期的动态积分随攻防队伍数量动态调整，对应分值随战队成功攻克或完成防御数量增加而递减。攻击成功与防御成功分别累计周期动态积分。最终按总分由高到低排名，同分则以提交时间为准，用时短者优先。最终得分=（当前队伍分数/最高队伍分数）*100分。表4 AWDP赛制考核内容题目类型类型描述Web应用服务考察选手对Web应用源码、框架逻辑和业务流程的安全分析能力，能够从PHP、Java、Python、Golang等常见开发语言及其运行环境中识别潜在风险，发现认证授权、输入校验、文件处理、反序列化等方面的安全问题。同时，要求选手具备对常见Web防护机制的理解与绕过分析能力，能够结合漏洞成因、代码逻辑和业务场景完成利用验证，并提出相应的修复与加固方案。二进制应用服务考查选手对Linux及嵌入式环境下二进制程序的逆向分析、漏洞定位和调试验证能力，能够运用静态分析与动态调试方法，识别栈溢出、堆溢出、UAF、格式化字符串等典型内存安全问题。选手需结合程序控制流、汇编指令、运行环境及保护机制，完成漏洞利用思路构造、指令级修补或ROP链分析，并进一步给出程序修复和安全加固建议。 四、比赛规则1.计分规则（1）团队计分每队由不多于4名参赛选手+不多于1名指导教师组成，成绩按照团队选手成绩计算。（2）总分加权算法总成绩计算分值为100分，具体分数占比如下：Build环节成绩占总比分权重5% + CTF解题赛成绩占总比分权重30% + 综合渗透赛成绩占总比分权重30% + AWDP攻防赛成绩占总比分权重35%。（3）初赛及分区赛成绩不计入决赛排名。2.比赛期间注意事项（1）每支参赛队的选手自备合规笔记本电脑1台、电源适配器、网络转接器等必须的设备,现场提供六类网络跳线；（2）为保证比赛公平及赛场用电安全，每个参赛队员限带一台笔记本电脑，额定功率不超过260W，以电源适配器标称额定功率为准；（3）禁止携带路由器、随身WiFi、手机热点、无线鼠标/键盘、无线耳机、存储设备、边缘AI计算设备等违规物品，所有设备须通过赛前安检；（4）选手需关闭浏览器的广告拦截插件和网络代理，保证平台的正常访问；（5）推荐选手使用Chrome或Firefox浏览器进行答题。若选手使用其他浏览器需自己负责兼容性问题；（6）在网络配置确认阶段和正式比赛期间，选手须使用同一台终端设备，防止因临时调换设备导致网络故障，影响答题；（7）比赛期间赛场将启用信号屏蔽设备，无线鼠标、无线键盘等无线设备可能无法使用，请选手自备有线设备。3.赛场规则（1）参赛队伍需提前30分钟到达比赛地点，凭有效证件核验身份后参赛。线下比赛前，所有参赛选手需将手机上交至组委会统一保管，赛后统一归还。比赛现场将为每支参赛队伍提供四个标准网络接口，参赛选手需自行携带笔记本电脑及兼容本人电脑的网络转接头。（2）选手需自备个人参赛工具：笔记本电脑、鼠标、鼠标垫、键盘、网口转接器，自己熟悉的参赛环境和常用软件、工具、脚本等。用于登录比赛系统的VPN、用户名和密码将在比赛签到时统一发放。（3）比赛过程中，参赛选手通过VPN的方式访问竞赛平台获取题目信息，赛题环境需要拨通VPN后进行访问（赛前提供选手操作手册）。每位参赛选手分配1个VPN账号，每个账号仅支持1台终端设备保持在线，不能在多个终端同时登录。（4）选手进入比赛环境后，系统将展示比赛状态、起止时间等信息，待比赛开始后可进入详情页进行比赛。比赛攻击时段可提交Flag，防守时段可上传防御包。更多信息请查询现场发放的操作手册。4.反作弊规则（1）禁止任何对比赛相关平台的暴力破解和攻击；（2）禁止DDoS、ARP等干扰比赛正常进行的攻击；（3）禁止任何针对参赛对手的网络攻击行为；（4）比赛过程中禁止参赛队伍之间分享任何解题思路及FLAG；（5）违规处罚采用轻度、中度、重度三级处罚体系：对场外交流、私连外网等轻度违规行为给予警告扣分；对恶意攻击非目标平台、篡改赛题环境等中度违规行为扣除该队50%总分；对作弊传题、恶意流量压测等重度违规行为取消参赛成绩并通报所属高校，全程记录留痕、可追溯取证。五、违规处理、举报申诉与仲裁规则为维护赛事公平公正，保障赛事顺利开展，现将违规处理、举报申诉与仲裁相关规定明确如下：1.违规处理出现以下情形，裁判组将立即取消参赛资格与比赛成绩，情节严重者将通报至参赛队伍所在高校。（1）参赛报名信息作弊或造假，包括但不限于编造成员身份、冒用他人身份参赛等；（2）在参赛过程中出现违反相关法律、法规的行为；（3）在参赛过程中经发现或被举报并认定存在违反赛事要求的行为，如抄袭他人成果、使用违规工具等。2.举报与申诉（1）举报流程：参赛选手若发现其他队伍违规，可进行实名举报，举报时须提交清晰、完整的佐证材料（如截图、视频、文字记录等），由大赛组委会秘书处负责受理。匿名举报或无有效佐证材料的举报将不予处理；（2）申诉流程：对成绩或评判存在异议的参赛选手，需在比赛结束后2天内，向大赛组委会秘书处提交书面申诉报告。报告内容应清晰地阐述申诉内容，详细说明争议点，并附参赛队伍指导教师及全体队员签名，未按要求提交的申诉将不予受理。3.仲裁机制大赛组委会秘书处负责接收举报和申诉材料，并提交技术委员会进行仲裁。技术委员会依据赛事规则、相关证据，对举报和申诉事项进行审议，其做出的仲裁结果为最终决定。举报和申诉的受理截止时间为比赛结束后2天内，逾期将不再受理。六、联络信息总决赛期间，具体活动时间以官网公布为准。赛事相关联系人：（Build环节）电话：郝老师18673175134（线下赛环节）电话：郑老师17377782635（酒店交通事务）电话：张老师 17668777939参赛选手QQ群：1094058805指导教师QQ群：1092498027大赛秘书处邮箱：1531734383@qq.com入住及交通推荐：                   出行路线及酒店推荐.docx七、其他赛事举行期间，参赛队伍及队员的交通、食宿费用需自理，请各位参赛人员自行安排好出行事宜，合理规划，确保按时参赛。如有任何疑问，请及时与赛事联系人沟通。本决赛规程的最终解释权归第十九届全国大学生信息安全竞赛——创新实践能力赛组委会所有。 第十九届全国大学生信息安全竞赛-创新实践能力赛竞赛组委会（齐鲁工业大学网络空间安全学院代章）2026年8月11日第十九届全国大学生信息安全竞赛创新实践能力赛（总决赛）参赛手册.pdf","category":"competition","status":"published","publishedAt":null,"discoveredAt":"2026-10-03T17:41:02.809Z","createdAt":"2026-10-03T17:41:02.809Z","updatedAt":"2026-10-11T15:45:57.836Z","summary":{"audience":["全国高校在校学生"],"bullets":["比赛时间：2026年8月29日—8月30日，地点：齐鲁工业大学长清校区-艺体中心。","参赛对象为经过初赛与半决赛后排名前80的队伍。","采用Build环节、CTF解题、综合渗透、AWDP攻防四种赛题模式。","总成绩权重：Build 5% + CTF 30% + 综合渗透 30% + AWDP 35%。","总决赛设全国一、二、三等奖及网络安全挑战创新单项奖。"],"keyDates":[{"label":"Build环节提交截止","date":"2026-08-18T00:00:00.000Z","evidence":"选手在平台提交结果截止时间为8月17日24时。"},{"label":"Build环节成绩公布","date":"2026-08-22T10:00:00.000Z","evidence":"8月22日10:00-18:00Build环节成绩公布"},{"label":"选手报到","date":"2026-08-28T14:00:00.000Z","evidence":"8月28日（星期五）14:00-18:00选手报到"},{"label":"比赛开始","date":"2026-08-29T09:00:00.000Z","evidence":"8月29日（星期六） 9:00-17:00比赛环节"},{"label":"比赛结束","date":"2026-08-30T14:00:00.000Z","evidence":"8月30日（星期日） 8:00-14:00比赛环节"}],"oneLine":"第十九届全国大学生信息安全竞赛创新实践能力赛总决赛于2026年8月29-30日在齐鲁工业大学举行。","sourceUrl":"http://www.ciscn.cn/index.php/announcement/view/418"},"categories":["competition"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626acb88ba001caa471772eda6','{"_id":"1233ab626acb88ba001caa471772eda6","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/977daa9ab8e240dbb1af6ea5b3b41ee1.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/977daa9ab8e240dbb1af6ea5b3b41ee1.htm","title":"研究生招生","contentText":"为方便候补考生查询，我院将通过官网更新2027年候补推免考生位置变动。\n更新时间：2026.9.24, 15:09\n\n报考学院\n专业\n已递补至第X名\n\n002计算机科学与技术学院\n081200计算机科学与技术（硕士）\n已录取完\n\n002计算机科学与技术学院\n085404计算机技术（硕士）\n已录取完\n\n002计算机科学与技术学院\n085410人工智能（硕士）\n已录取完","category":"college","status":"published","publishedAt":null,"discoveredAt":"2026-10-11T13:01:45.939Z","createdAt":"2026-10-11T13:01:45.939Z","updatedAt":"2026-10-11T15:46:08.703Z","summary":{"audience":["候补推免考生"],"bullets":["发布单位为北京交通大学计算机学院，内容为2027年候补推免考生位置变动查询。","更新时间：2026.9.24, 15:09。","002计算机科学与技术学院 081200计算机科学与技术（硕士）已录取完。","002计算机科学与技术学院 085404计算机技术（硕士）已录取完。","002计算机科学与技术学院 085410人工智能（硕士）已录取完。"],"keyDates":[],"oneLine":"北京交通大学计算机学院通过官网更新2027年候补推免考生位置变动，三个硕士专业均已录取完。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/977daa9ab8e240dbb1af6ea5b3b41ee1.htm"},"categories":["college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626acb88ba001caa495fa1dff3','{"_id":"1233ab626acb88ba001caa495fa1dff3","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/d6fc39edc9374eaaa3f16c00c0821f51.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/d6fc39edc9374eaaa3f16c00c0821f51.htm","title":"研究生招生","contentText":"各位考生，\n北京交通大学计算机科学与技术学院、国家卓越工程师学院（计算机技术专业）预推免复试考核结果（20260920）见附件：拟录取考生名单、候补考生名单。\n\n研招网推荐免试报考时限要求：\n1. 拟录取与候补考生须在2026年9月21日14：00前完成志愿填写，未按上述时间要求填报志愿，视为放弃报考，学院将不再保留其拟录取资格或候补资格，顺次递补。\n2. 学院在2026年9月22日上午9:00通过研招网向考生发送复试通知，9月24日上午8:00发送待录取通知，未在通知规定时间内完成复试确认或待录取通知确认的推免生，原则上学院将不再保留其拟录取资格，顺次递补。\n3. 已被其他志愿录取的考生，我院不再发送待录取通知，顺次递补。\n4. 未通过教育部“推免服务系统”（网址：https://yz.chsi.com.cn/tm/）确认的推免录取结果，一律无效。推免生接收工作结束后，推免生拟录取名单将在研究生院招生专题网公示。\n5. 候补考生位次更新情况将在学院官网上发布。\n\n北京交通大学计算机科学与技术学院\n2026年9月20日","category":"college","status":"published","publishedAt":null,"discoveredAt":"2026-10-11T13:01:46.846Z","createdAt":"2026-10-11T13:01:46.846Z","updatedAt":"2026-10-11T15:46:08.703Z","summary":{"audience":["拟录取考生","候补考生","推免生"],"bullets":["预推免复试考核结果（20260920）见附件：拟录取考生名单、候补考生名单。","拟录取与候补考生须在2026年9月21日14:00前完成志愿填写，否则视为放弃。","学院于2026年9月22日上午9:00发送复试通知，9月24日上午8:00发送待录取通知。","未通过教育部推免服务系统确认的录取结果无效，拟录取名单将在研究生院招生专题网公示。","候补考生位次更新情况将在学院官网上发布。"],"keyDates":[{"label":"志愿填写截止","date":"2026-09-21T14:00:00.000Z","evidence":"拟录取与候补考生须在2026年9月21日14：00前完成志愿填写"},{"label":"复试通知发送","date":"2026-09-22T09:00:00.000Z","evidence":"学院在2026年9月22日上午9:00通过研招网向考生发送复试通知"},{"label":"待录取通知发送","date":"2026-09-24T08:00:00.000Z","evidence":"9月24日上午8:00发送待录取通知"}],"oneLine":"北京交通大学计算机学院预推免复试考核结果公布，含拟录取与候补名单及后续填报时限。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/d6fc39edc9374eaaa3f16c00c0821f51.htm"},"categories":["college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
