INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626acb88c0001caa5002e72f7d','{"_id":"1233ab626acb88c0001caa5002e72f7d","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/8ce8fda50ff4483fbac2176c12a33b2b.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/8ce8fda50ff4483fbac2176c12a33b2b.htm","title":"研究生招生","contentText":"欢迎优秀应届本科毕业生推荐免试攻读北京交通大学计算机科学与技术学院硕士、博士研究生。\n一、申请条件\n1.拥护中国共产党的领导，愿为祖国建设服务，品德良好，遵纪守法；\n2.获得推荐学校推荐免试资格的优秀应届本科毕业生；\n3.学术研究兴趣浓厚，有较强的创新意识、创新能力和专业能力；\n4.身心健康，符合规定的体检要求。\n5.申请人获得所在学校推免生资格(如所在学校尚未完成推免资格评定工作，但预计可取得推免生资格者，也可申请)，最终拟录取结果以学生是否具有推免资格及复试成绩等决定。\n\n计算机科学与技术学院接收推荐免试硕士研究生（含直博生）专业\n\n专业代码\n专业名称\n是否接收推荐免试硕士研究生\n是否接收推荐免试直博生\n\n081200\n计算机科学与技术\n是\n是\n\n0812J1\n低空技术与工程\n是\n否\n\n085404\n计算机技术\n是\n是\n\n085410\n人工智能\n是\n是\n\n二、申请材料\n1.有效居民身份证；\n2.学信网学籍在线验证报告，请上传学信网上提供下载的PDF文件并确保报告在验真查询的有效期内；\n3.本科成绩单，教务部门公章。\n4.前三学年学习成绩排名证明，教务部门盖章。成绩排名证明中须能体现参评总人数，须为本科就读学校出具的最新推免排名，预报名系统所填排名信息须与成绩排名证明一致。\n5.学术科研成果（公开发表的论文、出版的专著等）、国家英语四（六）级成绩单、获奖证书等；\n6.申请直接攻读博士研究生者（直博生）还须提供《直博生个人陈述表》、两位申请攻读学位学科领域内的教授（或相当专业技术职称）专家的《直博生专家推荐书》（见附件）；\n上述申请材料由考生在我校推免预报名系统上传电子版图片，可通过对原件进行扫描或拍照生成，上传电子版为pdf或jpg格式，每个附件大小不超过1M。\n纸制版提交：考生来校计算机学院复试时，现场核验身份证原件，同时提供1-6纸制版材料，其中成绩单和排名证明要求盖章原件。\n申请人必须保证提供的全部申请材料以及网上报名信息的真实性和准确性。如果申请人提交的信息不真实或不准确，我校将取消申请人推免录取资格，并通报申请人所在学校，责任由申请人自负。\n三、流程\n1.申请\n（1）2026年9月8日00:00至2026年9月11日23:59，申请人登录北京交通大学研究生院招生专题网的“推免预报名系统”系统（网址：https://gsadmission.bjtu.edu.cn/recommend/signin/）进行预报名，按系统要求填写报名信息并上传申请材料，每个申请人只能填报一个志愿。\n（2）2026年9月11日前，申请人需联系意向导师。我院导师研究方向与联系方式参见：研究生院官网——“导师在线”栏目。\n（3）2026年9月21日，申请人（含已通过我校推免预报名复试的申请人）须登录教育部“推免服务系统”（网址：https://yz.chsi.com.cn/tm/）进行网上报名。\n教育部“推免服务系统”预计2026年9月21日9：00开通，如开通时间有变化，以最终实际开通时间为准。\n2.复试\n计算机学院预推免综合考核由导师组考核、学院考核（机试/面试）、报考材料审核三部分组成。关于导师组考核、复试通知发放、缴费确认、机试、面试等工作安排如下：\n（1）导师组考核（即日起至2026年9月11日中午12：00前 ）：学院组织导师成立导师考核小组，考核学生的学科专业知识、综合素质、创新能力以及外语水平。考核过程须本着公开公正的原则进行。考生必须在我校推免预报名系统中填报“推荐免试”志愿，与我院导师建立联系（我院导师研究方向与联系方式参见：研究生院官网——“导师在线”栏目），按照导师通知的考核时间参加导师组考核，导师考核小组通过邮件、电话、短信等途径发出考核通知，具体时间、方式等信息也由导师考核小组告知。导师组考核可采取网络远程或现场考核方式进行。导师考核小组将有意向接收并考核合格的申请人报送学院集中审核，导师小组报送考核通过名单截止时间：2026年9月11日12：00前。\n注意：夏令营入营同学也需要按上述流程完成推免预报名系统（网址：https://gsadmission.bjtu.edu.cn/recommend/signin/）报名，上传材料，填写“推荐免试”志愿，并联系导师进行导师小组复试考核。未在我校推免预报名系统提交“推荐免试”志愿的申请人，无法参加预推免复试进入后续的机试和材料审核环节。\n（2）预报名系统发放复试通知（2026年9月13日前）：学院根据申请人情况遴选、确定复试名单，在2026年9月13日前通过推免预报名系统向考生发送复试通知。\n（3）复试确认与复试缴费（2026年9月14日前）：考生必须在9月14日前完成推免预报名系统复试确认，并通过我校“推免缴费系统”交纳复试费(100元/人)，参加复试的考生均须缴纳复试费。缴费网址：https://gsadmission.bjtu.edu.cn/recommend/signin_new/\n（4）学院机试考核（2026年9月17日）：考生在规定时间通过推免预报名系统确认复试后，于2026年9月17日上午8点到逸夫楼西楼2层机房大厅完成身份核验，并提交第二部分中的纸制申请材料，查看机试分组时间。学院拟定于9月17日全天进行机试考核。\n附： 计算机科学与技术学院2027年推免生机试环境及要求、机试练习网站\n（5）直博生学院面试考核（2026年9月18日）：有意申请直博的9月全体预推免考生，除参加上述机试外，还需要参加由计算机学院组织的现场面试。面试时间：2026年9月18日上午9：00，复试地点：9教北111会议室。考核详细安排关注我院官网“研究生招生专题”发布的通知。\n（6）推免生申请材料审核（2026年9月19日）：学院成立材料审核专家组，对预推免申请人报名材料进行审核评分。\n（7）复试批次：学院将视录取情况确定是否增加后续复试批次。\n计算机学院预推免复试考核时间表\n\n日期\n工作安排\n备注\n\n即日起至9月11日\n考生联系导师，参加导师小组复试考核。\n\n9月8日-9月11日\n全体考生在我校预推免报名系统中填报“推荐免试”志愿\n夏令营入营考生也需要在推免预报名系统中报名\n\n9月11日12：00前\n导师报送导师小组复试通过考生名单\n\n9月13日前\n学院确定复试名单，发送复试通知\n\n9月14日前\n考生在预报名系统中确认复试，缴费复试费\n\n9月17日上午8：00\n复试考生验证、报到\n逸夫西2层\n\n9月17日全天\n分专业机试考核\n逸夫西2层\n\n9月18日上午9：00\n直博生面试\n计算机学院九教北111会议室\n\n9月19日\n报考材料评审打分\n\n9月20日前\n公布预推免考核拟录取名单与候补名单\n\n \n3.录取\n（1）复试结束后，学院将择优录取，确定拟录取名单与候补名单。\n（2）拟录取的推免生须按照教育部及学院要求，在规定时间内登录教育部“推免服务系统”（网址：https://yz.chsi.com.cn/tm），完成注册、填写个人基本信息、上传照片、网上支付、填写志愿、确认待录取等步骤，网报专业须与拟录取专业一致。\n   研招网推免服务系统志愿填报时间要求：考生在2026年9月21日中午12：00前完成志愿填写，未按上述时间要求填报志愿，视为放弃报考，学院将不再保留其拟录取资格或候补资格。未在规定时间内完成复试确认或待录取确认的推免生，原则上学院将不再保留其拟录取资格，学院可相应依次递补拟录取。\n（3）推免生一旦在教育部“推免服务系统”接受待录取通知，则不可再接受其它志愿的待录取通知。\n（4）拟录取的推免生不得再报名参加当年硕士研究生招生考试，否则取消其推免录取资格。\n（5）未通过教育部“推免服务系统”（网址http://yz.chsi.com.cn/tm/）确认的推免录取结果，一律无效。\n四、信息公示与监督联系方式：\n网站：考生请关注学院网站“研究生招生专题”栏目\n邮箱：jsjzs@bjtu.edu.cn\n电话：010-51685847\n附件：\n\n附件1：直博生个人陈述表.doc\n附件2：直博生专家推荐书.doc","category":"college","status":"published","publishedAt":null,"discoveredAt":"2026-10-11T13:01:52.855Z","createdAt":"2026-10-11T13:01:52.855Z","updatedAt":"2026-10-11T15:46:08.703Z","summary":{"audience":["优秀应届本科毕业生","获得推免资格的学生","申请直博的推免生"],"bullets":["申请条件：拥护党的领导、品德良好、获推免资格的优秀应届本科毕业生，学术兴趣浓厚、身心健康。","接收专业：计算机科学与技术、低空技术与工程、计算机技术、人工智能，其中低空技术与工程不接收直博生。","申请材料含身份证、学籍验证报告、成绩单、排名证明、科研成果及英语成绩等，直博生另需个人陈述表和专家推荐书。","流程包括预报名、联系导师、导师组考核、复试确认缴费、机试、直博面试、材料审核及教育部推免服务系统报名。","拟录取名单与候补名单于9月20日前公布，须在教育部推免服务系统完成确认方有效。"],"keyDates":[{"label":"预报名开始","date":"2026-09-08T00:00:00.000Z","evidence":"2026年9月8日00:00至2026年9月11日23:59，申请人登录北京交通大学研究生院招生专题网的“推免预报名系统”"},{"label":"预报名截止","date":"2026-09-11T23:59:00.000Z","evidence":"2026年9月8日00:00至2026年9月11日23:59"},{"label":"联系导师截止","date":"2026-09-11T00:00:00.000Z","evidence":"2026年9月11日前，申请人需联系意向导师。"},{"label":"导师组考核截止","date":"2026-09-11T12:00:00.000Z","evidence":"导师组考核（即日起至2026年9月11日中午12：00前 ）"},{"label":"导师报送名单截止","date":"2026-09-11T12:00:00.000Z","evidence":"导师小组报送考核通过名单截止时间：2026年9月11日12：00前。"},{"label":"复试通知发放截止","date":"2026-09-13T00:00:00.000Z","evidence":"预报名系统发放复试通知（2026年9月13日前）"},{"label":"复试确认与缴费截止","date":"2026-09-14T00:00:00.000Z","evidence":"复试确认与复试缴费（2026年9月14日前）：考生必须在9月14日前完成推免预报名系统复试确认"},{"label":"机试考核","date":"2026-09-17T08:00:00.000Z","evidence":"学院机试考核（2026年9月17日）：考生在规定时间通过推免预报名系统确认复试后，于2026年9月17日上午8点到逸夫楼西楼2层机房大厅完成身份核验"},{"label":"直博生面试","date":"2026-09-18T09:00:00.000Z","evidence":"直博生学院面试考核（2026年9月18日）：面试时间：2026年9月18日上午9：00"},{"label":"材料审核","date":"2026-09-19T00:00:00.000Z","evidence":"推免生申请材料审核（2026年9月19日）"},{"label":"拟录取名单公布截止","date":"2026-09-20T00:00:00.000Z","evidence":"9月20日前 公布预推免考核拟录取名单与候补名单"},{"label":"教育部推免服务系统报名","date":"2026-09-21T00:00:00.000Z","evidence":"2026年9月21日，申请人（含已通过我校推免预报名复试的申请人）须登录教育部“推免服务系统”"},{"label":"教育部推免服务系统志愿填报截止","date":"2026-09-21T12:00:00.000Z","evidence":"考生在2026年9月21日中午12：00前完成志愿填写"}],"oneLine":"北京交通大学计算机学院接收2027年推免硕士（含直博生）研究生，含申请条件、材料、流程与时间安排。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/8ce8fda50ff4483fbac2176c12a33b2b.htm"},"categories":["college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626acd73e6001f4d5833455f53','{"_id":"1233ab626acd73e6001f4d5833455f53","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/6dae5b7a496a4c1c935e519f2fb188d7.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/6dae5b7a496a4c1c935e519f2fb188d7.htm","title":"研究生招生","contentText":"北京交通大学计算机科学与技术学院2026年全国优秀大学生暑期夏令营入营通知已经通过报名系统发放，请及时进入我院报名系统（csapply.bjtu.edu.cn）确认是否入营。\n\n学校地址：北京市海淀区上园村3号北京交通大学，进入校园请出示身份证。\n营员报到地址：第九教学楼北楼111会议室（由于学院正门正在施工，营员可从第九教学楼西侧门进入学院）\n联系电话：010-51685847\n服务邮箱：jsjzs@bjtu.edu.cn\n联系人：研究生服务中心 周老师 9教北205B办公室","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:26.729Z","createdAt":"2026-10-12T23:57:26.729Z","updatedAt":"2026-10-12T23:57:31.160Z","summary":{"audience":["全国优秀大学生","入营营员"],"bullets":["入营通知已通过报名系统发放，请进入 csapply.bjtu.edu.cn 确认是否入营。","营员报到地址为第九教学楼北楼111会议室，因学院正门施工可从第九教学楼西侧门进入。","进入校园请出示身份证，学校地址为北京市海淀区上园村3号。","联系电话：010-51685847，服务邮箱：jsjzs@bjtu.edu.cn。","联系人：研究生服务中心 周老师，9教北205B办公室。"],"keyDates":[],"oneLine":"北京交通大学计算机学院2026年优秀大学生暑期夏令营入营通知已通过报名系统发放，请及时确认。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/6dae5b7a496a4c1c935e519f2fb188d7.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626acd73ec001f4d6736ee6ff0','{"_id":"1233ab626acd73ec001f4d6736ee6ff0","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/28bef730474649b090ea9e4c622a9583.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/28bef730474649b090ea9e4c622a9583.htm","title":"研究生招生","contentText":"教务部门盖章的成绩单和排名，可以盖学院的章吗？可以的。\n夏令营系统注册收不到验证码？请仔细检查所写邮箱是否正确。后缀以选项形式勾选，不要把@后的信息写重复了。\n系统打不开？清理浏览器缓存后，再重新打开网址。\n学院以什么方式通知入营？邮件通知，申请人在系统中确认是否入营。\n推免创新系统未开放？2026年7月举办的计算机学院夏令营活动报名网址为：https://csapply.bjtu.edu.cn/login","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:32.732Z","createdAt":"2026-10-12T23:57:32.732Z","updatedAt":"2026-10-12T23:57:37.208Z","summary":{"audience":["研究生申请人","夏令营申请人"],"bullets":["教务部门盖章的成绩单和排名可以盖学院的章。","夏令营系统注册收不到验证码时，请检查邮箱是否正确，后缀以选项形式勾选，避免@后信息重复。","系统打不开时，清理浏览器缓存后重新打开网址。","学院通过邮件通知入营，申请人在系统中确认是否入营。","2026年7月举办的计算机学院夏令营活动报名网址为：https://csapply.bjtu.edu.cn/login"],"keyDates":[],"oneLine":"北京交通大学计算机学院研究生招生夏令营常见问题解答及报名网址说明。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/28bef730474649b090ea9e4c622a9583.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','1233ab626acd73ee001f4d6a6f53a4db','{"_id":"1233ab626acd73ee001f4d6a6f53a4db","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/yjstd/yjstz/0d06f9f4012849b29af4ba796c060592.htm","originalUrl":"https://cs.bjtu.edu.cn/yjstd/yjstz/0d06f9f4012849b29af4ba796c060592.htm","title":"研究生教育","contentText":"关于2026年夏季学期研究生课程开课及选课\n相关事宜的通知\n \n为助力研究生新生高效衔接入学后的专业学习，系统完善课程前置知识体系，加速融入科研实践进程，电信学院与计算机学院将于 2026年夏季学期，继续面向全校研究生开展夏季学期课程教学。现将课程安排及选课相关事宜通知如下：\n一、开设课程\n\n序号\n开课学院\n课程类型\n课程号\n课程名\n面向学生学院\n学生类型\n\n1\n电信学院\n专业课\nM601043B\n高级深度学习\n电信学院\n全日制、非全日制研究生、詹天佑学院高年级本科生\n\n2\n计算机学院\n平台课\nC402002B\n深度学习\n不限\n全日制、非全日制研究生、詹天佑学院高年级本科生\n\n3\n平台课\nC402017B\n智能计算数学基础\n非计算机学院\n全日制、非全日制研究生、詹天佑学院高年级本科生\n\n4\n专业课\nM502019B\n深度学习\n计算机学院\n全日制、非全日制研究生、詹天佑学院高年级本科生、计算机科学与技术（拔尖试点班）\n\n5\n专业课\nM502034B\n高级软件研发实践\n计算机学院\n非全日制研究生\n\n具体上课时间及课程选课说明见附件一。\n二、选课时间\n正选时间：6月29日9:00——7月1日24:00（第18教学周一至周三）\n退补选时间：7月7日9:00——7月12日24:00（夏季学期第1教学周周二至周日）\n此阶段仅供夏季学期课程选课，不进行秋季学期课程选课。退补选截止日期为7月12日，退补选结束前，请务必登录教学支撑平台认真核对选课课表，确认选课是否正确。退补选阶段结束后将不再接受任何选课和退课的操作。且后续秋季课程选课期间，不再开放与夏季学期课程相关的操作。\n三、上课时间\n夏季学期上课时间：7月7日——8月29日\n注意：选课时显示的夏季学期课程上课时间非实际上课时间，实际上课时间请查询本通知附件中的课表。\n四、授课方式\n夏季学期课程将采用网上授课的方式进行教学。具体上课所使用的教学平台，请于正选结束后及时进入课程微信群，听从任课老师安排，课程微信群二维码请在正选结束后从教学支撑平台查看。\n五、其他\n1. 由学院根据新生使用的培养方案对信息能力的要求，决定是否通知本学院2026级新生在夏季学期选修课程。具体选课操作说明请查看附件二。\n2. 夏季学期课程成绩记入2026年秋季学期成绩。\n3. 因2026级博士研究生招生工作还未完成，学生名单还未确定，学生暂无学号。电信学院及计算机学院仅面向本学院博士生开放选课，暂不开放外院博士选课。\n4. 因2026级学生还未完成报到注册等入学手续，2026级学生当前为“拟录取”状态，学校提供夏季学期课程修课机会不与最终录取名单挂钩。\n5. 夏季学期课程后续相关事宜，请学生及时关注“北京交通大学教学支撑平台”中的通知。\n\n附件：\n 1--关于2026年夏季学期研究生课程开课及选课相关事宜的通知\n2-计算机学院关于夏季学期研究生选课补充说明\n3--2026年夏季计算机学院研究生课程课表\n4-计算机学院夏季学期开设课程基本情况表\n5--附件一 选课说明（2026）\n6--附件二 操作说明\n7-2026春季学期校历\n\n \n计算机科学与技术学院\n2026年6月24日","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:34.711Z","createdAt":"2026-10-12T23:57:34.711Z","updatedAt":"2026-10-12T23:57:39.150Z","summary":{"audience":["全日制研究生","非全日制研究生","詹天佑学院高年级本科生","计算机科学与技术（拔尖试点班）"],"bullets":["开设5门课程，含高级深度学习、深度学习、智能计算数学基础、高级软件研发实践等","正选时间：6月29日9:00至7月1日24:00；退补选时间：7月7日9:00至7月12日24:00","夏季学期上课时间：7月7日至8月29日，采用网上授课方式","夏季学期课程成绩记入2026年秋季学期成绩","2026级博士生暂不开放外院选课，2026级学生当前为拟录取状态"],"keyDates":[{"label":"正选开始","date":"2026-06-29T09:00:00.000Z","evidence":"正选时间：6月29日9:00——7月1日24:00（第18教学周一至周三）"},{"label":"正选结束","date":"2026-07-02T00:00:00.000Z","evidence":"正选时间：6月29日9:00——7月1日24:00（第18教学周一至周三）"},{"label":"退补选开始","date":"2026-07-07T09:00:00.000Z","evidence":"退补选时间：7月7日9:00——7月12日24:00（夏季学期第1教学周周二至周日）"},{"label":"退补选截止","date":"2026-07-13T00:00:00.000Z","evidence":"退补选时间：7月7日9:00——7月12日24:00（夏季学期第1教学周周二至周日）"},{"label":"上课开始","date":"2026-07-07T00:00:00.000Z","evidence":"夏季学期上课时间：7月7日——8月29日"},{"label":"上课结束","date":"2026-08-29T00:00:00.000Z","evidence":"夏季学期上课时间：7月7日——8月29日"}],"oneLine":"电信学院与计算机学院2026年夏季学期研究生课程开课及选课安排通知","sourceUrl":"https://cs.bjtu.edu.cn/yjstd/yjstz/0d06f9f4012849b29af4ba796c060592.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66ac13e15000351ab19056729','{"_id":"15ff78a66ac13e15000351ab19056729","sourceId":"e04862b86ac1382a000398b22c855cce","sourceName":"蓝桥杯大赛 · 赛事信息页","canonicalUrl":"https://dasai.lanqiao.cn/pages/v7/dasai/competition/individual_competition.html","originalUrl":"https://dasai.lanqiao.cn/pages/v7/dasai/competition/individual_competition.html","title":"蓝桥杯大赛 · 赛事信息页","contentText":"参赛方式\n\n学生个人实名认证\n\n选择院校报名\n\n院校筛选并添加指导老师\n\n缴费并填写发票信息\n\n下载准考证\n\n参加考试\n\n参赛对象\n\n科目\n\n组别\n\n参赛对象\n\n参赛形式\n\nJAVA软件开发\n\n设研究生组、大学A组、大学B组、大学C组\n\n具有正式学籍的在校全日制研究生、本科及高职高专学生(以报名时状态为准)\n\n以个人为单位进行比赛\n\nC/C++程序设计\n\n设研究生组、大学A组、大学B组、大学C组\n\nPython程序设计\n\n设研究生组、大学A组、大学B组、大学C组\n\nWeb应用开发\n\n设大学组和职业院校组\n\n网络安全\n设大学组\n\n软件测试\n设大学组\n\n鸿蒙应用开发\n设大学组和职业院校组\n\n嵌入式设计与开发\n设大学组\n\n单片机设计与开发\n设大学组和职业院校组\n\n物联网设计与开发\n设大学组\n\nEDA设计与开发\n设大学组\n\nFPGA设计与开发\n设大学组\n\n5G全网规划与建设\n设大学组\n\n组别说明\n\n研究生只能报研究生组\n985、211本科生只能报大学A组及以上组别\n其它院校本科生可自行选择报大学B组及以上组别\n高职高专院校可报大学C组/职业院校组或自行选择任意组别\n\n报名时间\n\n软件电子赛报名时间：2025年10月20日10:00—2026年3月11日14:00\n鸿蒙应用开发报名时间：2025年11月19日10:00—2026年3月11日14:00\n\n报名须知\n\n人数及方式\n\n以学校为单位报名。\n各参赛学校需为每位参赛选手配备一名指导教师，每名选手的指导教师最多一名，报多名的以排序第一的为准，其余无效。同一名指导教师可指导多位选手。\n\n报名材料\n\n报名表\n身份证复印件\n学生证复印件\n2寸相片\n以上均需要电子扫描版，通过报名系统上传\n\n报名及参赛费用\n\n科目报名费为300元/人\n选手及指导老师（或家长）在省赛、决赛期间发生的住宿、用餐、交通等费用自理；\n报名费由蓝桥杯大赛组委会收取。\n\n组织工作\n\n大赛的报名、交费、下载准考证等工作全部通过蓝桥杯官网在线报名系统完成。","category":"competition","status":"published","publishedAt":null,"discoveredAt":"2026-10-03T17:40:37.098Z","createdAt":"2026-10-03T17:40:37.098Z","updatedAt":"2026-10-11T15:46:14.492Z","summary":{"audience":["具有正式学籍的在校全日制研究生","具有正式学籍的在校全日制本科学生","具有正式学籍的在校全日制高职高专学生"],"bullets":["参赛流程：学生个人实名认证、选择院校报名、院校筛选并添加指导老师、缴费并填写发票信息、下载准考证、参加考试。","参赛对象为具有正式学籍的在校全日制研究生、本科及高职高专学生，以个人为单位进行比赛。","科目包括JAVA软件开发、C/C++程序设计、Python程序设计、Web应用开发、网络安全、软件测试、鸿蒙应用开发、嵌入式设计与开发、单片机设计与开发、物联网设计与开发、EDA设计与开发、FPGA设计与开发、5G全网规划与建设。","报名以学校为单位，需配备指导教师，报名费300元/人，报名、交费、下载准考证均通过蓝桥杯官网在线报名系统完成。","软件电子赛报名时间：2025年10月20日10:00—2026年3月11日14:00；鸿蒙应用开发报名时间：2025年11月19日10:00—2026年3月11日14:00。"],"keyDates":[{"label":"软件电子赛报名截止","date":"2026-03-11T14:00:00.000Z","evidence":"软件电子赛报名时间：2025年10月20日10:00—2026年3月11日14:00"},{"label":"鸿蒙应用开发报名截止","date":"2026-03-11T14:00:00.000Z","evidence":"鸿蒙应用开发报名时间：2025年11月19日10:00—2026年3月11日14:00"}],"oneLine":"蓝桥杯大赛赛事信息，含参赛方式、对象、科目组别、报名时间及费用等。","sourceUrl":"https://dasai.lanqiao.cn/pages/v7/dasai/competition/individual_competition.html"},"categories":["competition"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66ac13e2f000351b84694d73d','{"_id":"15ff78a66ac13e2f000351b84694d73d","sourceId":"e04862b86ac1382a000398b37064a885","sourceName":"全国大学生信息安全竞赛 · 通知公告","canonicalUrl":"http://www.ciscn.cn/index.php/announcement/view/417","originalUrl":"http://www.ciscn.cn/index.php/announcement/view/417","title":"全国大学生信息安全竞赛官方网站","contentText":"第十九届全国大学生信息安全竞赛创新实践能力赛总决赛通知——山泉汇聚建教育特色靶场，科教融合砺网安时代尖兵各晋级赛队：恭喜各晋级赛队成功入围第十九届全国大学生信息安全竞赛创新实践能力赛总决赛！本届大赛自启动以来，吸引了全国（含香港、澳门特别行政区）804所高校的4150支队伍、逾万名学子参与。经过全国线上初赛和全国五大赛区层层选拔，最终遴选出80支优秀队伍入围全国总决赛。本届总决赛由教育部高等学校网络空间安全专业教学指导委员会主办，齐鲁工业大学（山东省科学院）承办，定于2026年8月29日至30日在山东省济南市举行，参赛队伍须于8月28日报到。为便于联系，请各参赛队员和指导教师务必分别加入学生QQ群：1094058805和教师QQ群：1092498027。详细的场地、日程及住宿安排等信息见后续官网通知。济南地处齐鲁腹地，是山东省省会，别称\"泉城\"，因境内泉水众多而闻名于世，历史文化底蕴深厚，趵突泉、大明湖、千佛山等人文自然景观交相辉映。此外，济南是中国北方重要的中心城市和综合交通枢纽，京沪高铁、京港澳高速纵贯南北，区位优势突出，为赛事举办提供了优越的交通与保障条件。齐鲁工业大学（山东省科学院）坐落于泉城济南，是山东省重点建设的应用研究型大学，山东省属高校高水平大学\"冲一流\"建设高校。学校由原齐鲁工业大学与山东省科学院合并组建，实行校院合一管理体制，科教融合优势突出，是山东省新型工业科技创新及人才培养领域的重要力量。学校计算机学科是山东省\"高峰学科\"，在2024年软科中国学科排名中位列全国第25位（前9%），位次连年攀升，居山东高校前列，网络空间安全人才培养特色鲜明，办赛条件保障有力。山泉汇聚，建教育特色靶场；科教融合，砺网安时代尖兵。我们将依托齐鲁工业大学（山东省科学院）\"科教融合\"的办学优势，全力为本次赛事打造独具特色的网络安全实战靶场，期待来自全国各地的青年才俊齐聚泉城，以赛会友，交流切磋，共同砺炼新时代网络安全尖兵本色，赛出大学生的青春风采，齐鲁工业大学（山东省科学院）热忱期盼您的到来！附件：决赛入围队伍名单  第十九届全国大学生信息安全竞赛——创新实践能力赛竞赛组委会（齐鲁工业大学网络空间安全学院代章）2026年8月8日第十九届全国大学生信息安全竞赛创新实践能力赛总决赛通知.pdf附件-决赛入围队伍名单.xlsx","category":"competition","status":"published","publishedAt":null,"discoveredAt":"2026-10-03T17:41:03.306Z","createdAt":"2026-10-03T17:41:03.306Z","updatedAt":"2026-10-11T15:45:57.836Z","summary":{"audience":["各晋级赛队","参赛队员","指导教师"],"bullets":["总决赛由教育部高等学校网络空间安全专业教学指导委员会主办，齐鲁工业大学（山东省科学院）承办。","比赛定于2026年8月29日至30日在山东省济南市举行，参赛队伍须于8月28日报到。","本届大赛吸引全国804所高校的4150支队伍参与，最终遴选出80支优秀队伍入围全国总决赛。","参赛队员和指导教师须分别加入学生QQ群1094058805和教师QQ群1092498027。","详细场地、日程及住宿安排等信息见后续官网通知。"],"keyDates":[{"label":"报到日期","date":"2026-08-28T00:00:00.000Z","evidence":"参赛队伍须于8月28日报到"},{"label":"比赛开始","date":"2026-08-29T00:00:00.000Z","evidence":"定于2026年8月29日至30日在山东省济南市举行"},{"label":"比赛结束","date":"2026-08-30T00:00:00.000Z","evidence":"定于2026年8月29日至30日在山东省济南市举行"},{"label":"公告日期","date":"2026-08-08T00:00:00.000Z","evidence":"2026年8月8日"}],"oneLine":"第十九届全国大学生信息安全竞赛创新实践能力赛总决赛定于2026年8月29日至30日在济南举行，80支队伍入围。","sourceUrl":"http://www.ciscn.cn/index.php/announcement/view/417"},"categories":["competition"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66acb88bb000bcde62a22b69d','{"_id":"15ff78a66acb88bb000bcde62a22b69d","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/798364256a96493196e421895380532a.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/798364256a96493196e421895380532a.htm","title":"研究生招生","contentText":"各位考生，\n请查看北京交通大学计算机科学与技术学院2027年推免生机试日程安排。\n1.机试分组\n\n组号\n报考学院\n专业代码\n专业\n验证、提交报考材料时间\n进入机房时间\n机试时间\n提前交卷离开考场\n\n1\n002计算机科学与技术学院\n081200\n计算机科学与技术\n9月17日上午7:30-8:30\n9月17日上午8:30\n9月17日上午9:00-11:00，开考15分钟后不得进入考场\n禁止\n\n2\n002计算机科学与技术学院\n085404\n计算机技术\n9月17日上午11:00-12:00\n9月17日下午12:00\n9月17日中午12:30-14:30，开考15分钟后不得进入考场\n禁止\n\n3\n002计算机科学与技术学院\n085410\n人工智能\n9月17日上午11:00-12:00\n9月17日下午12:00\n9月17日中午12:30-14:30，开考15分钟后不得进入考场\n禁止\n\n4\n904国家卓越工程师学院\n085404\n计算机技术（卓工计划）\n9月17日上午14:30-15:30\n9月17日下午15:30\n9月17日下午16:00-18:00，开考15分钟后不得进入考场\n禁止\n\n注意：直博申请人也需要参加机试\n\n2.机试地点：北京市海淀区上园村3号北京交通大学逸夫教学楼（西楼）2层机房。考生在9月17日当天可持预报名系统中导出的《北京交通大学2027年招收推荐免试攻读硕士（博士）研究生申请表》，刷身份证原件进入校园。\n3.入场路线：从逸夫教学楼（西楼）值班室南侧露天楼梯到达2层天台，完成现场报到，提交纸制报考材料，等候进入机房。\n4.考试结束离场路线：从机房门右侧的走廊楼梯，有序离场。\n5.请提前按以下顺序装订纸制报考材料：\n\n（1）有效居民身份证（携带原件核验身份，并提交1份复印件，在人像处用签字笔注明“仅用于推免复试身份核验”）；\n（2）学信网《教育部学籍在线验证报告》1份；\n（3）本科成绩单（须加盖教务部门公章）；\n（4）教务部门盖章的最新成绩排名证明（证明中需包含姓名、总人数及排名位次，须由学校或学院教务部门出具并盖章。预报名系统中填写的排名信息须与此纸质证明一致；如不一致，务必在纸质版上予以注明）；\n（5）学术科研成果（公开发表的论文、出版的专著等）、国家英语四（六）级成绩单、获奖证书等。\n6. 如有任何问题，请及时通过jsjzs@bjtu.edu.cn或报考导师反馈。","category":"college","status":"published","publishedAt":null,"discoveredAt":"2026-10-11T13:01:47.811Z","createdAt":"2026-10-11T13:01:47.811Z","updatedAt":"2026-10-11T15:46:08.703Z","summary":{"audience":["2027年推免生","直博申请人"],"bullets":["机试分组：计算机科学与技术、计算机技术、人工智能、计算机技术（卓工计划）四组，时间从9月17日上午7:30至下午18:00不等。","机试地点：北京市海淀区上园村3号北京交通大学逸夫教学楼（西楼）2层机房。","入场路线：从逸夫教学楼（西楼）值班室南侧露天楼梯到达2层天台，完成现场报到、提交纸质材料后等候进入机房。","考试结束离场路线：从机房门右侧的走廊楼梯有序离场。","直博申请人也需要参加机试；纸质报考材料需按指定顺序装订。"],"keyDates":[{"label":"机试日期","date":"2027-09-17T00:00:00.000Z","evidence":"9月17日上午7:30-8:30"}],"oneLine":"北京交通大学计算机学院发布2027年推免生机试日程安排，含分组、时间、地点及材料要求。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/798364256a96493196e421895380532a.htm"},"categories":["college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66acb88bd000bcdea67f22f2d','{"_id":"15ff78a66acb88bd000bcdea67f22f2d","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/e468bfa6543445ea8f873e9833030b1e.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/e468bfa6543445ea8f873e9833030b1e.htm","title":"研究生招生","contentText":"各位考生，\n计算机科学与技术学院2027年预推免考核复试通知已经通过我校预推免系统发放。\n一、复试确认与缴费：\n考生于9月14日中午12:00前在预报名系统中完成复试确认并缴纳复试费。\n复试确认网址：https://gsadmission.bjtu.edu.cn/recommend/signin/\n复试缴费网址：https://gsadmission.bjtu.edu.cn/recommend/signin_new/\n二、参加机试：\n进入复试的考生于9月17日到达逸夫楼西楼2层机房大厅验证、报到，参加机试考核。机试报到详细安排另行通知。\n三、机试报到地点：\n北京市海淀区上园村3号北京交通大学逸夫教学楼（西楼）2层。考生在9月17日当天可持预报名系统中导出的《北京交通大学2027年招收推荐免试攻读硕士（博士）研究生申请表》，刷身份证进入校园。\n四、机试身份核验与纸制报考材料提交\n请提前准备以下纸质材料，按顺序装订，在验证报到时提交。现场报到时，查看机试分组名单。\n1.有效居民身份证（携带原件核验身份，并提交1份复印件，在人像处用签字笔注明“仅用于推免复试身份核验”）；\n2.学信网《教育部学籍在线验证报告》1份；\n3.本科成绩单（须加盖教务部门公章）；\n4.教务部门盖章的最新成绩排名证明（证明中需包含姓名、总人数及排名位次，须由学校或学院教务部门出具并盖章。预报名系统中填写的排名信息须与此纸质证明一致；如不一致，务必在纸质版上予以注明）；\n5.学术科研成果（公开发表的论文、出版的专著等）、国家英语四（六）级成绩单、获奖证书等。\n五、如您决定放弃参加机试，请及时告知报考导师并邮件通知jsjzs@bjtu.edu.cn，邮件主题请注明：姓名-本科学校-放弃复试。\n六、如有任何问题，请及时通过jsjzs@bjtu.edu.cn或报考导师反馈。","category":"college","status":"published","publishedAt":null,"discoveredAt":"2026-10-11T13:01:49.791Z","createdAt":"2026-10-11T13:01:49.791Z","updatedAt":"2026-10-11T15:46:08.703Z","summary":{"audience":["进入复试的考生"],"bullets":["复试确认与缴费：9月14日中午12:00前在预报名系统完成确认并缴费。","机试：9月17日到逸夫楼西楼2层机房大厅验证、报到，参加机试考核。","报到地点：北京市海淀区上园村3号北京交通大学逸夫教学楼（西楼）2层，可刷身份证进校。","需提交装订纸质材料：身份证复印件、学籍在线验证报告、成绩单、成绩排名证明、科研成果及证书等。","放弃机试须告知报考导师并邮件通知jsjzs@bjtu.edu.cn，主题注明姓名-本科学校-放弃复试。"],"keyDates":[{"label":"复试确认与缴费截止","date":"2027-09-14T12:00:00.000Z","evidence":"考生于9月14日中午12:00前在预报名系统中完成复试确认并缴纳复试费。"},{"label":"机试报到","date":"2027-09-17T00:00:00.000Z","evidence":"进入复试的考生于9月17日到达逸夫楼西楼2层机房大厅验证、报到，参加机试考核。"}],"oneLine":"北京交通大学计算机学院2027年预推免复试通知：9月14日前确认缴费，9月17日机试报到。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/e468bfa6543445ea8f873e9833030b1e.htm"},"categories":["college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66acb88bf000bcdef63f70773','{"_id":"15ff78a66acb88bf000bcdef63f70773","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/20ecc413aa854846aaa12f4e682ab62d.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/20ecc413aa854846aaa12f4e682ab62d.htm","title":"研究生招生","contentText":"面试时间：2026年9月18日上午9：00面试开始。8：30-8：50至9教北111室拷贝PPT，持身份证原件核验证件。\n面试地点：北京交通大学9教北111会议室\n考核内容：考生须准备8分钟PPT，对自己的本科专业背景、学习及研究成果、攻博研究设想、学习动机等进行简要的阐述。考核专家组将进行现场提问，重点考察申请人的学术兴趣、创新能力、创新意识、研究潜质等。\n直博生复试通知通过邮件发送，请及时回复是否参加面试。注意：直博考生也需要参加9月17日学院组织的上机考试，详情参见机试复试通知邮件。","category":"college","status":"published","publishedAt":null,"discoveredAt":"2026-10-11T13:01:51.803Z","createdAt":"2026-10-11T13:01:51.803Z","updatedAt":"2026-10-11T15:46:08.703Z","summary":{"audience":["研究生考生","直博考生"],"bullets":["面试时间：2026年9月18日上午9:00开始，8:30-8:50至9教北111室拷贝PPT并持身份证原件核验证件。","面试地点：北京交通大学9教北111会议室。","考核内容：考生准备8分钟PPT阐述本科专业背景、学习及研究成果、攻博研究设想、学习动机等，专家组现场提问考察学术兴趣、创新能力、创新意识、研究潜质等。","直博生复试通知通过邮件发送，请及时回复是否参加面试。","直博考生也需参加9月17日学院组织的上机考试，详情参见机试复试通知邮件。"],"keyDates":[{"label":"面试开始","date":"2026-09-18T09:00:00.000Z","evidence":"面试时间：2026年9月18日上午9：00面试开始。"},{"label":"上机考试","date":"2026-09-17T00:00:00.000Z","evidence":"直博考生也需要参加9月17日学院组织的上机考试"}],"oneLine":"北京交通大学计算机学院研究生招生面试于2026年9月18日举行，直博生需参加9月17日上机考试。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/20ecc413aa854846aaa12f4e682ab62d.htm"},"categories":["college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66acd73e4000e62f210e55c3c','{"_id":"15ff78a66acd73e4000e62f210e55c3c","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/74e7f9ee649847acb3ec66543eada977.htm","originalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/74e7f9ee649847acb3ec66543eada977.htm","title":"本科生教育","contentText":"全体同学：\n2026年9月3日、9月4日学校将组织2025-2026学年春季学期课程的补考，具体安排如下：\n一、报名资格和报名方式  \n1.报名资格\n（1）有补考报名资格，且有意愿参加补考的同学。具体政策请参见最新版《北京交通大学考试管理规定》、《北京交通大学成绩管理规定》。\n（2）期末考试申请缓考获得批准的同学，必须到网上报名后方可参加考试。\n2.报名方式\n本次补考采用先报名后考试的方式，同学们需在规定时间内通过学校教务系统网上报名确认无误后参加补考。\n二、时间安排\n1.网上报名。7月14日9:00至7月15日15:00，请同学们在网上报名，具体报名方式为：以学生身份登录教学运行中心主页（http://toc.bjtu.edu.cn），进入“用户登录”选择“学生登录”，进入后，选择“教务系统”中的“考务成绩”模块，查看“我的考试”。\n2.查询考场安排。7月16日以后，已报名的同学可以查询补考具体时间地点（查看方式同网上报名）。\n3.补考。9月3日、9月4日。\n三、注意事项\n1.申请缓考获批准的同学必须报名后方可参加考试，未报名者不能参加补考。申请缓考获批但未参加补考的课程成绩将记为零分或者“F”，备注“缺考”。\n2.7月15日15:00报名截止后，不再受理任何形式的报名，请务必按时报名。\n3.补考成绩最高记60分或“D”，不合格的按实际成绩记载或记为“F”。","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:24.648Z","createdAt":"2026-10-12T23:57:24.648Z","updatedAt":"2026-10-12T23:57:32.396Z","summary":{"audience":["有补考报名资格且有意愿参加补考的同学","期末考试申请缓考获得批准的同学"],"bullets":["补考时间为2026年9月3日、9月4日。","网上报名时间为7月14日9:00至7月15日15:00，通过教学运行中心教务系统报名。","7月16日以后可查询补考具体时间地点。","申请缓考获批准的同学必须报名后方可参加考试，未报名者不能参加补考。","补考成绩最高记60分或“D”，不合格按实际成绩记载或记为“F”。"],"keyDates":[{"label":"报名开始","date":"2026-07-14T09:00:00.000Z","evidence":"7月14日9:00至7月15日15:00"},{"label":"报名截止","date":"2026-07-15T15:00:00.000Z","evidence":"7月14日9:00至7月15日15:00"},{"label":"查询考场安排","date":"2026-07-16T00:00:00.000Z","evidence":"7月16日以后，已报名的同学可以查询补考具体时间地点"},{"label":"补考开始","date":"2026-09-03T00:00:00.000Z","evidence":"2026年9月3日、9月4日学校将组织2025-2026学年春季学期课程的补考"},{"label":"补考结束","date":"2026-09-04T00:00:00.000Z","evidence":"2026年9月3日、9月4日学校将组织2025-2026学年春季学期课程的补考"}],"oneLine":"2025-2026学年春季学期课程补考于9月3日、9月4日举行，需先网上报名。","sourceUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/74e7f9ee649847acb3ec66543eada977.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66acd73e7000e62f63dad1a34','{"_id":"15ff78a66acd73e7000e62f63dad1a34","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/a89f871d970b4b11bca26aafc28fae50.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/a89f871d970b4b11bca26aafc28fae50.htm","title":"研究生招生","contentText":"https://w17icl91.yichafen.com/qz/119gJI7PPt\n请输入学号和姓名查询。","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:27.689Z","createdAt":"2026-10-12T23:57:27.689Z","updatedAt":"2026-10-12T23:57:31.037Z","summary":{"audience":["研究生招生相关考生"],"bullets":["公告标题为研究生招生","来源为北京交通大学计算机学院通知公告","公告提供查询链接 https://w17icl91.yichafen.com/qz/119gJI7PPt","查询方式为输入学号和姓名"],"keyDates":[],"oneLine":"北京交通大学计算机学院发布研究生招生查询入口，需输入学号和姓名查询。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/a89f871d970b4b11bca26aafc28fae50.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66acd73e8000e62f73cd331d6','{"_id":"15ff78a66acd73e8000e62f73cd331d6","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/045bf4456d594c4d99678233d9a16e8a.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/045bf4456d594c4d99678233d9a16e8a.htm","title":"研究生招生","contentText":"北京交通大学计算机科学与技术学院2026年全国优秀大学生暑期夏令营日程表：附件\n7月10日导师团队实验室开放日导引：附件","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:28.690Z","createdAt":"2026-10-12T23:57:28.690Z","updatedAt":"2026-10-12T23:57:31.174Z","summary":{"audience":["全国优秀大学生"],"bullets":["北京交通大学计算机科学与技术学院发布2026年全国优秀大学生暑期夏令营日程表，以附件形式提供。","发布7月10日导师团队实验室开放日导引，以附件形式提供。","公告来源为北京交通大学计算机学院通知公告。","公告标题为研究生招生。"],"keyDates":[],"oneLine":"北京交通大学计算机学院发布2026年全国优秀大学生暑期夏令营日程表及7月10日导师团队实验室开放日导引。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/045bf4456d594c4d99678233d9a16e8a.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','15ff78a66acd73ed000e63016d357056','{"_id":"15ff78a66acd73ed000e63016d357056","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/4127a25aa35c4c928aeefb0c0fc48edc.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/4127a25aa35c4c928aeefb0c0fc48edc.htm","title":"研究生招生","contentText":"我院2026级硕士研究生录取通知书发放工作安排如下：\n一、发放时间及方式\n1. 发放范围：政审表已寄达的全日制非定向应届生；政审+档案已经寄达的全日制非定向往届生；政审+告知书已经寄达的非全日制定向生。\n2.  EMS寄送：\n\n        统一寄出时间：2026年6月29日\n        邮寄方式：EMS特快专递\n\n3.  现场提前领取：\n        领取时间：2026年6月27日10:00-12:00。未现场领取的通知书，6月29日通过EMS寄出。\n        领取地点：9号教学楼北205B室\n        所需材料：本人身份证原件（代领需提供双方身份证复印件及授权委托书）\n二、注意事项\n1. 选择现场领取的考生，请务必在规定时间内领取。\n2. 相关材料未到的同学，录取通知书缓发，材料齐备后陆续寄出。\n计算机科学与技术学院\n2026年6月26日","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:33.716Z","createdAt":"2026-10-12T23:57:33.716Z","updatedAt":"2026-10-12T23:57:38.050Z","summary":{"audience":["2026级硕士研究生新生"],"bullets":["发放范围：政审表已寄达的全日制非定向应届生；政审+档案已寄达的全日制非定向往届生；政审+告知书已寄达的非全日制定向生。","现场提前领取时间：2026年6月27日10:00-12:00，地点：9号教学楼北205B室。","现场领取需本人身份证原件，代领需双方身份证复印件及授权委托书。","未现场领取的通知书于2026年6月29日通过EMS特快专递统一寄出。","材料未到的同学录取通知书缓发，材料齐备后陆续寄出。"],"keyDates":[{"label":"现场领取时间","date":"2026-06-27T10:00:00.000Z","evidence":"领取时间：2026年6月27日10:00-12:00"},{"label":"EMS统一寄出时间","date":"2026-06-29T00:00:00.000Z","evidence":"统一寄出时间：2026年6月29日"}],"oneLine":"计算机学院2026级硕士录取通知书6月27日可现场领取，6月29日统一EMS寄出。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/4127a25aa35c4c928aeefb0c0fc48edc.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','bda3c2dc6ac13e2d00047a3c30f3b137','{"_id":"bda3c2dc6ac13e2d00047a3c30f3b137","sourceId":"e04862b86ac1382a000398b37064a885","sourceName":"全国大学生信息安全竞赛 · 通知公告","canonicalUrl":"http://www.ciscn.cn/index.php/announcement/view/419","originalUrl":"http://www.ciscn.cn/index.php/announcement/view/419","title":"全国大学生信息安全竞赛官方网站","contentText":"随着网络攻击日趋智能化、规模化、复杂化，传统人工溯源模式难以适配智能安全运营的高效处置需求，企业安全运营中仍存在多源数据割裂、证据关联困难、攻击链路复盘不完整、分析经验难沉淀等问题。本届比赛 Build 环节以“基于多源日志的攻击溯源工程”为主题，围绕综合企业环境中的多源安全数据，考察参赛队伍对攻击者痕迹的工程化提取、归一化建模、时间线还原和攻击路径图谱构建能力。Build环节设置创新实践榜单，并以5% 的总分占比计入战队总分。Build 环节成果将在比赛结束后面向参赛队伍进行分享交流，用于促进各队伍在安全数据工程、攻击链路分析和自动化溯源方法上的相互学习。一、基本信息时间环节内容8月12日赛题分发发布选手题目附件包、选手手册和样例提交；选手熟悉数据结构、提交格式和本地校验工具。发布方式：通过选手预留邮箱发送赛题数据包，数据包内包含赛题、操作方式、上传方式等比赛操作所需指导文件。发布对象：赛题附件包发送到参赛队伍预留的领队联系邮箱，如未能收到或领队信息有变可及时联系组委会服务人员处理解决。8月12日至17日Build竞赛答题与提交选手完成多源日志、PCAP、Windows Event XML 等证据分析，构建证据数据集、攻击时间线、IOC 和攻击路径图谱。选手根据赛题数据包内的要求对完成的赛题内容通过预留的赛题平台上传。上传截止时间为8月17日23时59分59秒。登录方式：报名预留手机号加验证码登录；队伍上传提交时使用唯一 token 进行认证。注：每队最多 3 次上传机会，系统取该队最高分进入 Build 环节排行榜；上传文件为 submission.zip，最大 30MB，解压后最大 80MB，平台自动解包、校验和评分。manifest.json 中的 team_id 必须与队伍 token 对应编号一致。到规定时间冻结提交通道并完成客观评分。评分会根据要求发送到参赛选手的邮箱。8月17日至21日结果复核与成果整理组委会技术裁判会根据选手上传的赛题答案进行评分，包括系统自动评定及人工复核，组委会会针对异常提交进行答案及内容的复核。8月22日Build赛成绩公布公布Build环节成绩。二、赛制介绍2.1 题目设计考查重点l 多源异构安全数据处理能力，包括 CSV、JSONL、纯文本日志、PCAP 和 Windows Event XML 等数据类型的解析与关联。l 攻击链条关联分析能力，能够从外部入口、主机失陷、跳板利用、横向移动、数据收集和外传等阶段中还原攻击路径。l 自动化证据抽取与归一化能力，能够将日志和 artifact 证据统一映射到可评分的 event_id。l 攻击路径图谱建模能力，能够用节点和边表达攻击者、主机、账号、服务、数据库、文件、域名等实体关系。l 面向平台评分的工程化提交能力，能够按照固定 schema 输出可解析、可验证、可复现的结构化结果。2.2 比赛任务要求主办方将提供一个模拟真实企业的五天多源取证附件包。包含资产清单、账号清单、网络分区、边界设备日志、网络流量日志、Linux/Windows 主机日志、应用审计、数据库审计、云与容器审计、安全告警、PCAP 流量包和 Windows Event XML 导出。参赛队伍需要从附件包中识别成功发生且对攻击链有因果贡献的行为，提交结构化证据、时间线、IOC 和攻击路径拓扑。本题不以 flag 为核心目标，也不要求提交自然语言报告。所有得分均由固定字段与标准答案自动比对计算；多报无关事件会降低准确率。2.2.1 攻击者痕迹证据数据集构建任务背景：企业真实安全运营场景中，攻击证据通常分散在不同设备、不同格式、不同时间窗口的日志与流量材料中，单一日志源很难完整支撑攻击链路判断。任务目标：从主办方数据包中提取攻击者相关证据，形成可由平台自动评分的证据数据集、时间线和 IOC 集合。识别外部攻击入口、命令执行、持久化、凭据访问、凭据使用、发现、横向移动、数据收集、规避和外传等关键阶段证据。PCAP与Windows Event XML为正式证据源，选手必须将分析得到的packet或XML event映射为artifact event_id后提交。只提交成功发生且对后续攻击链有因果贡献的行为；失败登录、拒绝访问、正常扫描、正常发布和正常备份等噪声不应作为攻击路径提交。2.2.2 攻击路径拓扑图谱构建任务背景：复杂入侵往往不是单一路径，而是一个入口、一个或多个跳板、多条并行分支和最终汇总外传的组合过程。任务目标：围绕攻击者、主机、账号、文件、服务、数据库、云资源和外联域名等实体，构建攻击路径拓扑图。攻击图节点应表达攻击涉及的核心实体，如 IP、主机、账号、文件、服务、数据库、域名、对象存储桶和 Kubernetes 集群。攻击图边应表达实体之间的攻击行为关系，包括 from、to、action、stage、time_start、time_end 和 evidence_ids。选手可以直接编写 attack_graph.json，也可以先维护 graph_nodes.csv 和 graph_edges.csv，再使用工具生成 attack_graph.json。攻击图应覆盖主路径和并行分支，避免只提交入口攻击或只提交单条线性路径。三、提交文件与格式最终提交文件为 submission.zip，解压后根目录应直接包含以下核心文件：文件是否必需说明manifest.json必需队伍标识、schema 版本和生成时间等提交元信息。evidence.csv必需攻击证据列表；字段要求见选手手册与 submission_schema.md。timeline.csv必需攻击时间线；字段要求见选手手册与 submission_schema.md。attack_graph.json必需攻击路径图谱，顶层包含 schema_version、incident_id、nodes 和 edges。ioc.csv必需IOC 集合，包含 IP、域名、文件、账号、token 等指标。graph_nodes.csv / graph_edges.csv可选用于辅助生成 attack_graph.json；平台最终以 attack_graph.json 为准。 平台只读取固定核心文件，并按照字段枚举、引用关系和标准答案进行客观计算。正式提交前，建议队伍使用数据包内 tools/validator.py 对提交目录进行本地校验，确认文件完整、JSON/CSV 可解析、event_id 与 evidence_id 引用关系正确。四、评分规则Build 环节总分 100 分，全部为客观自动评分，不设置人工主观分。评分项如下：评分项分值评分说明格式合规10严格检查文件、schema、枚举、时间、唯一性和引用关系；任一错误使本次提交无效，总分为 0。证据发现25按 event_id 命中情况计算 precision、recall 和 F1。攻击阶段分类10检查命中关键证据的 stage 是否正确。时间线还原15保序一对一匹配；必需证据 70%、stage 15%、起止时间各 7.5%。拓扑节点10规范化实体集合按 precision、recall 和 F1 评分。拓扑边关系20from/to 40%、action 15%、stage 15%、时间 10%、必需证据 20%，再计算质量 F1。IOC 提取10type/value F1 占 7 分，时间、关联资产和证据元数据占 3 分。为避免通过堆叠可疑事件刷分，证据发现和图谱关系评分均强调准确率与召回率的平衡。选手应提交经过分析确认的攻击证据，而不是提交全部可疑日志。PCAP 和 Windows Event XML 中的 artifact event_id 与普通日志event_id 使用同一套评分口径。五、操作指南5.1 平台登录比赛平台开放后，选手使用规定方式登录。首次进入 Build 环节页面后，应核对队伍信息和队伍 token。5.2 下载赛题数据包进入 Build 环节页面后下载选手数据包，优先阅读 README.md、docs/player_manual.md、docs/submission_schema.md 和 docs/sample_submission/。5.3 本地分析与校验先阅读 env/ 下的资产、账号、网段和服务关系，建立企业环境上下文。结合 logs/ 和 artifacts/ 进行多源关联分析，将确认的证据写入 evidence.csv。根据证据构建 timeline.csv、attack_graph.json 和 ioc.csv。使用 tools/validator.py 进行本地格式校验。validator 仅代表格式和引用关系通过，不代表最终得分。5.4 上传文件点击平台上传入口，选择 submission.zip 并提交。单个 zip 最大 30MB，解压后最大 80MB。5.5 查看结果平台完成自动解包、校验和评分后，显示本次提交结果。每队最多 3 次上传机会，最终取最高分进入 Build 环节排行榜。六、注意事项参赛团队须独立完成全部分析、构建与提交内容，严禁复制、抄袭或交换其他队伍成果。选手不得攻击、干扰比赛平台或其他队伍环境，不得提交恶意文件或与比赛任务无关的内容。提交文件应遵守主办方给出的固定格式。文件缺失、字段错误、引用不存在或压缩包目录层级错误会使本次提交无效并计为一次上传。比赛过程中如遇平台访问、数据包下载、提交失败等问题，请通过竞赛官方沟通渠道联系工作人员，并保留必要的错误截图和提交时间信息。本 Build 环节相关规则及未尽事宜，最终解释权归第十九届全国大学生信息安全竞赛创新实践能力赛竞赛组委会所有。 第十九届全国大学生信息安全竞赛——创新实践能力赛竞赛组委会（齐鲁工业大学网络空间安全学院代章）                         2026年8月12日附：第十九届全国大学生信息安全竞赛创新实践能力赛决赛队伍名单序号队伍名称学校名称所属赛区1Lilac哈尔滨工业大学辽宁赛区2天枢 Dubhe北京邮电大学辽宁赛区30psu3中国人民公安大学辽宁赛区4Calil哈尔滨工业大学辽宁赛区5redbud清华大学辽宁赛区6Opsu3中国人民公安大学辽宁赛区7圣地亚哥皮蛋山东警察学院辽宁赛区8Spirit-Grad吉林大学辽宁赛区9Rrwebb大连民族大学辽宁赛区10HASHTEAM山东大学辽宁赛区11老谭酸菜面中国科学院大学辽宁赛区12BlueWhale中国海洋大学辽宁赛区13TimeKeeper山东科技大学辽宁赛区14AAA浙江大学浙江赛区15Ph0t1n1a上海交通大学浙江赛区160x3B宁波工程学院浙江赛区17Sn0w南京理工大学浙江赛区180RAYS杭州电子科技大学浙江赛区19一剑霜寒十四州！浙江警察学院浙江赛区20白泽复旦大学浙江赛区21EDI-NU1315-1合肥师范学院浙江赛区22不管了直接加钠安徽师范大学浙江赛区23A1natas浙江师范大学浙江赛区24雨蓝上海公安学院浙江赛区25农奴宁波城市职业技术学院浙江赛区26SimpleGipsy杭州师范大学浙江赛区270x04温州商学院浙江赛区28hnnutech淮南师范学院浙江赛区29tluSec铜陵学院浙江赛区30crychic上海交通大学浙江赛区31cha0s郑州轻工业大学湖北赛区32SSSec007郑州大学湖北赛区33SeeU-Sec中国人民警察大学湖北赛区34Fotsec安阳工学院湖北赛区35彩虹七号郑州警察学院湖北赛区36NYSEC南阳理工学院湖北赛区37All1n武汉大学湖北赛区38witctf武汉工程大学湖北赛区39babyL3H华中科技大学湖北赛区40NEUQR0东北大学秦皇岛分校湖北赛区41云帆 NSN河北大学湖北赛区42CTF_Forerver华中科技大学湖北赛区43sssec777郑州大学湖北赛区44TorchWood江西警察学院广东赛区45烽火戏诸侯南昌大学广东赛区46广外女生广东外语外贸大学广东赛区47火炬木江西警察学院广东赛区48风信子江西师范大学广东赛区49BinX广州大学广东赛区50WYE五邑大学广东赛区51Become广东轻工职业技术大学广东赛区52广外幽灵广东外语外贸大学广东赛区53我搞丢了可乐和鸡排暨南大学广东赛区54NISA-325Spark福建师范大学广东赛区55Xp0int暨南大学广东赛区56SumY2i3国防科技大学重庆赛区570x401四川大学重庆赛区58NSTL电子科技大学重庆赛区59网安笑传之长城杯国防科技大学重庆赛区60Xu7e45重庆电子科技职业大学重庆赛区61Dino成都理工大学重庆赛区62LVV湖南警察学院重庆赛区63AegisForce四川文理学院重庆赛区640xFA重庆邮电大学重庆赛区65D1no成都理工大学重庆赛区66Flyteam西南民族大学重庆赛区67挂科不可耻，ctf0 解遗臭万年贵州大学重庆赛区68莫问西安理工大学陕西赛区69N05ecUltra兰州大学陕西赛区70N05ecMax兰州大学陕西赛区71XJUSEC-只是回忆上了发条新疆大学陕西赛区72F14GThi3f西安邮电大学陕西赛区73L_2026西安电子科技大学陕西赛区74NWU0SEC西北大学陕西赛区75Starfall Koi西安电子科技大学陕西赛区76JK西北工业大学陕西赛区77Taru1塔里木大学陕西赛区78甲壳虫安全团队新疆财经大学陕西赛区79我想把回忆拼好给你--终