INSERT INTO campus_documents(collection,id,body) VALUES('items','bda3c2dc6acd73e10014a5390ea08cd5','{"_id":"bda3c2dc6acd73e10014a5390ea08cd5","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/00b22e6f3a214da1830a9157c466370f.htm","originalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/00b22e6f3a214da1830a9157c466370f.htm","title":"本科生教育","contentText":"各位2023级同学，大家好！\n  附件是《计算机科学与技术学院推荐2027届优秀应届本科毕业生免试攻读研究生工作实施细则》，请查收。\n\n                                       计算机学院教学科\n                                        2026年9月7日","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:21.817Z","createdAt":"2026-10-12T23:57:21.817Z","updatedAt":"2026-10-12T23:57:31.112Z","summary":{"audience":["2023级同学"],"bullets":["公告对象为2023级同学。","附件为《计算机科学与技术学院推荐2027届优秀应届本科毕业生免试攻读研究生工作实施细则》。","公告要求同学查收附件。","发布单位为计算机学院教学科。","公告落款日期为2026年9月7日。"],"keyDates":[],"oneLine":"计算机学院向2023级同学发送推免工作实施细则附件，请查收。","sourceUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/00b22e6f3a214da1830a9157c466370f.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','bda3c2dc6acd73e20014a53e17c4e880','{"_id":"bda3c2dc6acd73e20014a53e17c4e880","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/81a2058107a04e8993053a3eaa00b8cd.htm","originalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/81a2058107a04e8993053a3eaa00b8cd.htm","title":"本科生教育","contentText":"各位2023级同学，大家好！\n  附件是《关于推荐2027届优秀应届本科毕业生免试攻读研究生工作办法的通知》、《关于科研创新素养模块认定的补充说明》，请查收。\n\n                                       计算机学院教学科\n                                        2026年9月7日","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:22.741Z","createdAt":"2026-10-12T23:57:22.741Z","updatedAt":"2026-10-12T23:57:31.239Z","summary":{"audience":["2023级同学"],"bullets":["面向2023级同学发布通知","附件为《关于推荐2027届优秀应届本科毕业生免试攻读研究生工作办法的通知》","附件为《关于科研创新素养模块认定的补充说明》","发布单位为计算机学院教学科","发布日期为2026年9月7日"],"keyDates":[],"oneLine":"计算机学院向2023级同学发送推免工作办法及科研创新素养模块认定补充说明附件。","sourceUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/81a2058107a04e8993053a3eaa00b8cd.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','bda3c2dc6acd73e30014a5450077ab48','{"_id":"bda3c2dc6acd73e30014a5450077ab48","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/efeecd8aa9d14a20b1ea45bff1867f1a.htm","originalUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/efeecd8aa9d14a20b1ea45bff1867f1a.htm","title":"本科生教育","contentText":"各位同学\n依据学校关于2026年暑假放假安排的通知，下学期本科生开学注册时间为2026年9月5日、9月6日（周六、日）两天，9月7日（周一）开始上课。具体工作安排如下：\n一、工作要求\n1、严格报到注册程序。学生持本人证件按时报到，禁止代替他人报到，杜绝漏报、错报，确保学校掌握每个学生的状态。\n2、提高报送数据的准确性。各学院应按规定时间报送各类表格，确保数据的准确性和规范性，后续本科生院将结合休学、复学、考勤记录等对报到注册情况进行检查。\n二、报到注册工作安排\n1、本次报到注册工作利用“本科生自助报到注册一体机”进行，一体机报到注册系统开放时间为9月3日10:00至9月6日22:00，机器放置位置见下表。本科生院将于9月6日22点统计各学院按时报到率，9月7日系统继续开放，统计最终报到注册情况。\n\n2、因人脸识别不通过等原因无法在自助报到注册一体机进行报到的学生，请于9月6日下午14：30-16：00到计算机教学科（九教北108A）进行人工报到注册。请假延迟返校的，请于返校后第一时间到就近自助机器上进行报到注册。\n3、对于未请假未报到、请假逾期未归的学生，学院应第一时间进行公示，以公示形式通知其2周内到校报到注册，否则将按照相关规定给予退学处理。\n4、按照《北京交通大学本科生学籍管理规定》“学生不能按时报到，必须事先向所在学院请假，请假三天以上的由所在学院报学校本科生院备案”的规定，不能及时返校报到的，请在教务系统中进行请假备案。\n5、按照《北京交通大学本科生学籍管理规定》第四十条第6款 “未请假或请假未获批准离校连续两周及以上未参加学校规定的教育教学活动的”、第7款“超过学校规定期限未注册而又无正当事由的”，应当予以退学，学院整理公示材料并通知学生来校办理退学手续。\n6、按照学校要求，欠缴学费学生将无法在系统中进行注册。\n三、复学手续办理\n因休学期满、参加国际交流项目结束、参军退伍等需要复学的学生，均应在开学一周内登录教务系统办理复学手续。按照《北京交通大学本科生学籍管理规定》第四十条第3款“休学或保留学籍期满，逾期两周未办理复学手续的”，应当予以退学，学院整理公示材料并通知学生来校办理退学手续。","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:23.669Z","createdAt":"2026-10-12T23:57:23.669Z","updatedAt":"2026-10-12T23:57:33.103Z","summary":{"audience":["本科生","需复学的学生","各学院"],"bullets":["下学期本科生开学注册时间为2026年9月5日、9月6日两天，9月7日（周一）开始上课。","报到注册使用“本科生自助报到注册一体机”，系统开放时间为9月3日10:00至9月6日22:00。","人脸识别不通过等原因无法自助报到的学生，请于9月6日下午14:30-16:00到计算机教学科（九教北108A）人工报到注册。","不能按时报到须事先向所在学院请假，请假三天以上由学院报本科生院备案，并在教务系统中请假备案。","欠缴学费学生将无法在系统中进行注册；复学学生应在开学一周内登录教务系统办理复学手续。"],"keyDates":[{"label":"自助报到注册系统开放开始","date":"2026-09-03T10:00:00.000Z","evidence":"一体机报到注册系统开放时间为9月3日10:00至9月6日22:00"},{"label":"开学注册","date":"2026-09-05T00:00:00.000Z","evidence":"下学期本科生开学注册时间为2026年9月5日、9月6日（周六、日）两天"},{"label":"开学注册","date":"2026-09-06T00:00:00.000Z","evidence":"下学期本科生开学注册时间为2026年9月5日、9月6日（周六、日）两天"},{"label":"自助报到注册系统开放结束","date":"2026-09-06T22:00:00.000Z","evidence":"一体机报到注册系统开放时间为9月3日10:00至9月6日22:00"},{"label":"人工报到注册","date":"2026-09-06T14:30:00.000Z","evidence":"请于9月6日下午14：30-16：00到计算机教学科（九教北108A）进行人工报到注册"},{"label":"开始上课","date":"2026-09-07T00:00:00.000Z","evidence":"9月7日（周一）开始上课"}],"oneLine":"本科生下学期9月5日、6日报到注册，9月7日上课，自助机9月3日10:00开放。","sourceUrl":"https://cs.bjtu.edu.cn/bkstd/bkstz/efeecd8aa9d14a20b1ea45bff1867f1a.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','bda3c2dc6acd73e50014a55569e0d573','{"_id":"bda3c2dc6acd73e50014a55569e0d573","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/d159499dd1de40949b198519c8ae905d.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/d159499dd1de40949b198519c8ae905d.htm","title":"研究生招生","contentText":"各位营员：\n    北京市气象台2026年7月9日发布暴雨橙色预警，依据北京市教委及学校防汛办关于暴雨橙色预警应急处置相关要求，为切实保障各位同学人身安全，经学院研究决定，对7月10日（周五）夏令营活动安排调整如下：\n一、活动时间调整\n    原定7月10日下午的“导师实验室开放与导师见面活动”提前至当日11:00开始，预计夏令营于12:00提前结束；上午的夏令营宣讲会按原计划举行。\n二、行程建议\n1. 建议京外尚未出发人员及居住地距我校海淀校区较远、需长途出行的营员，取消7月10日到校行程；\n2. 已入住学校周边宾馆或在校内的营员，欢迎按上述调整后的时间前往现场参加线下活动。\n三、安全提示\n    请全体营员密切关注气象预警信息，暴雨预警时段尽量减少外出，注意出行安全，做好个人防范。\n    北京交通大学计算机科学与技术学院\n2026年7月9日","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:25.650Z","createdAt":"2026-10-12T23:57:25.650Z","updatedAt":"2026-10-12T23:57:32.000Z","summary":{"audience":["营员"],"bullets":["北京市气象台2026年7月9日发布暴雨橙色预警，学院调整7月10日（周五）夏令营活动安排。","原定7月10日下午的“导师实验室开放与导师见面活动”提前至当日11:00开始，预计夏令营于12:00提前结束。","上午的夏令营宣讲会按原计划举行。","建议京外尚未出发及居住地距海淀校区较远、需长途出行的营员取消7月10日到校行程。","已入住学校周边宾馆或在校内的营员，欢迎按调整后时间前往现场参加线下活动。"],"keyDates":[{"label":"活动日期","date":"2026-07-10T00:00:00.000Z","evidence":"对7月10日（周五）夏令营活动安排调整如下"},{"label":"公告发布日","date":"2026-07-09T00:00:00.000Z","evidence":"2026年7月9日"}],"oneLine":"因暴雨橙色预警，7月10日夏令营活动提前至11:00开始，预计12:00结束。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/d159499dd1de40949b198519c8ae905d.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','e04862b86acb88be0009ba4e5da208aa','{"_id":"e04862b86acb88be0009ba4e5da208aa","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/tzgg/5430656e07e2464d8802c751f731645a.htm","originalUrl":"https://cs.bjtu.edu.cn/tzgg/5430656e07e2464d8802c751f731645a.htm","title":"通知公告","contentText":"各位同学：\n根据学校《关于科研创新素养模块认定的补充说明》及学院推免工作细则要求，申请科研创新素养加分的同学须参加学院组织的公开答辩，由专家组对成果的真实性、原创性及个人实际贡献进行审核鉴定。现将本次答辩相关事宜通知如下：\n一、答辩时间与地点\n答辩时间：拟定于2026年9月11日（周五）上午8：30开始，以最新通知为准。\n候场地点：思源西楼 SX201。\n请各位同学提前30分钟到达候场地点签到并拷贝PPT，具体答辩分组、答辩顺序将于当日在候场教室公布。\n二、答辩材料\n1、答辩PPT（模板见附件）：答辩当天携带至现场进行拷贝。\n2、获奖证书原件：答辩当天携带至现场供评委审核。\n3、指导教师亲笔署名的推荐信：联合参赛、与指导教师联合发表论文的成果，须提交指导教师亲笔署名（手写签名）的推荐信，客观陈述学生在联合成果中的实际贡献。推荐信同样在答辩当天现场提交供评委审核。\n三、答辩流程\n1、在候场地点签到、获取分组信息后到对应的教室拷贝PPT。\n2、个人陈述（不超过4分钟）：结合PPT，重点介绍本人申请加分的科研创新成果的背景、个人承担的具体工作、技术/学术创新点、实际贡献等。请勿照读论文摘要或项目结题报告，应聚焦“我做了什么”、“成果是什么”、“创新在哪里”。\n3、专家提问与答辩：专家组将就成果的真实性、原创性、个人贡献及学术规范性等进行提问，请如实作答。\n四、答辩PPT制作要求\n1、成果含以下核心内容：申请加分的成果信息（不申请加分的不要包含在内）、每项成果中本人的具体研究工作（附证据）、创新点说明、个人贡献等，不得直接复制粘贴论文全文或项目报告大段文字。\n2、竞赛需说明大赛主办方、参赛队伍规模、设奖情况、队内排名与个人贡献等。\n3、论文需说明每个作者的单位、合作情况、论文创新点、个人贡献等。\n4、专利需提供专利证书、原始申报技术材料等。\n五、注意事项\n1、不按时参加答辩，视为放弃科研创新素养模块加分，此模块加分记为0分。\n2、所有提交材料须保证真实、原创，如发现抄袭、造假、冒名等情况，一经查实，将取消本次推免资格并按学校相关规定处理。\n3、答辩当天请携带本人学生证及身份证以备核验身份。\n4、答辩结束后，审核结果将按学校要求在学院网站及公告栏进行公示，请关注后续通知。\n计算机科学与技术学院教学科2026年9月8日\n附件：科研创新素养加分PPT模板","category":"college","status":"published","publishedAt":null,"discoveredAt":"2026-10-11T13:01:50.795Z","createdAt":"2026-10-11T13:01:50.795Z","updatedAt":"2026-10-11T15:46:08.703Z","summary":{"audience":["申请科研创新素养加分的同学"],"bullets":["答辩拟定于2026年9月11日（周五）上午8：30开始，以最新通知为准，候场地点为思源西楼SX201。","须提前30分钟到场签到并拷贝PPT，答辩分组与顺序当日公布。","答辩材料包括PPT、获奖证书原件，以及联合成果所需的指导教师亲笔署名推荐信。","个人陈述不超过4分钟，专家就真实性、原创性、个人贡献及学术规范性提问。","不按时参加答辩视为放弃加分记0分，材料造假将取消推免资格。"],"keyDates":[{"label":"答辩时间","date":"2026-09-11T08:30:00.000Z","evidence":"答辩时间：拟定于2026年9月11日（周五）上午8：30开始，以最新通知为准。"}],"oneLine":"计算机学院通知科研创新素养加分公开答辩事宜，拟定2026年9月11日举行。","sourceUrl":"https://cs.bjtu.edu.cn/tzgg/5430656e07e2464d8802c751f731645a.htm"},"categories":["college"]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','e04862b86acd73ef000b1a4e42b9594b','{"_id":"e04862b86acd73ef000b1a4e42b9594b","sourceId":"15ff78a66acb889d000bcdb945e4c113","sourceName":"北京交通大学 · 计算机学院通知公告","canonicalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/43d0504187d64309b1a97154f22a7e1d.htm","originalUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/43d0504187d64309b1a97154f22a7e1d.htm","title":"研究生招生","contentText":"为促进全国优秀大学生学术交流，增进青年学生对计算机相关学科的了解，北京交通大学计算机科学与技术学院拟面向全国高校2027届应届本科毕业生举办2026年全国优秀大学生暑期夏令营活动。\n一、报名条件\n申请者须品德良好，遵纪守法，身心健康，并满足以下条件之一：\n1. 本校应届本科毕业生，专业成绩排名前40%（詹天佑学院学生排名要求可适当放宽）；\n2. 同类高校应届本科毕业生，专业成绩排名前40%（特色班可根据实际情况适当放宽）；\n3. 具有相关优势学科的高校应届本科毕业生，专业成绩排名前10%；\n4. 在各类重大学科竞赛获全国二等奖以上奖励者（含二等奖），或作为第一发明人获批专利，或以第一作者发表A类论文（内容须与报考专业相关）。\n二、申请材料\n1. 有效期内的居民身份证(报到时持原件备查）；\n2. 学信网《教育部学籍在线验证报告》（在线下载PDF版，需在核验有效期内）；\n3. 本科前三学年（如无，则前五学期）成绩单（教务部门盖章，PDF格式）；\n4. 本科前三学年（如无，则前五学期）成绩排名证明（教务部门盖章）；\n5. 国家英语四级或六级成绩单（≥425分）；\n6. 其他能力证明材料（获奖证书、论文、专利等）。\n申请人将上述申请材料上传至夏令营报名系统。每个附件大小不超过1M，请按系统要求顺序进行上传。申请人必须保证全部申请材料的真实性和准确性。如果申请人提交的信息不真实或不准确，我校将取消申请人营员资格，责任由申请人自负。入营日现场验证提交1.2.5.6复印件，3.4原件，按序号排序装订。\n三、报名方式\n1. 网上报名：登录我校夏令营报名系统csapply.bjtu.edu.cn提交申请。\n2. 截止时间：2026年7月6日下午18：00。\n3. 入营查询：审核结果将通过报名系统发布，不接受电话咨询，未入选者不另行通知。\n四、夏令营工作安排\n夏令营活动安排如下表所示，具体日程安排详见后续通知。\n\n日期\n活动内容\n\n7月6日下午18:00\n报名截止\n\n7月10日8:00-12:00\n营员报到、材料核验、招生宣讲\n\n7月10日13:30-17:00\n导师实验室营员接待活动\n\n五、关于2026年暑期夏令营活动的说明与温馨提示\n1. 导师对接\n营员通过我校研究生院官网“导师在线”栏目查阅导师研究方向与招生专业信息，并主动联系意向导师团队沟通交流。\n2. 夏令营活动内容\n本次夏令营面向全国拟通过推免方式报考我院各专业的2027届应届本科毕业生，活动内容包括介绍我院研究生培养特色、招生政策及学科优势；组织营员与导师团队交流，促进双向了解。\n夏令营为招生宣传活动，不设选拔考核、优秀营员评选及任何形式的录取承诺。\n3.  北京交通大学计算机科学与技术学院对夏令营活动拥有最终解释权。\n六、联系方式\n咨询电话：010-51685847，夏令营营员服务信箱：jsjzs@bjtu.edu.cn。\n学院和学科介绍等更多相关内容请查阅计算机科学与技术学院官网：https://cs.bjtu.edu.cn","category":"college","categories":["college"],"status":"published","publishedAt":null,"discoveredAt":"2026-10-12T23:57:35.717Z","createdAt":"2026-10-12T23:57:35.717Z","updatedAt":"2026-10-12T23:57:38.542Z","summary":{"audience":["全国高校2027届应届本科毕业生","拟通过推免方式报考北京交通大学计算机科学与技术学院各专业的学生"],"bullets":["面向全国高校2027届应届本科毕业生，拟通过推免方式报考该院各专业。","报名条件包括专业成绩排名要求，或在重大学科竞赛获全国二等奖以上、获批专利、发表A类论文等。","申请材料含身份证、学籍在线验证报告、成绩单、成绩排名证明、四六级成绩单及其他能力证明材料。","通过夏令营报名系统csapply.bjtu.edu.cn网上报名，截止时间为2026年7月6日下午18:00。","夏令营为招生宣传活动，不设选拔考核、优秀营员评选及任何形式的录取承诺。"],"keyDates":[{"label":"报名截止","date":"2026-07-06T18:00:00.000Z","evidence":"截止时间：2026年7月6日下午18：00。"},{"label":"营员报到、材料核验、招生宣讲","date":"2026-07-10T08:00:00.000Z","evidence":"7月10日8:00-12:00 营员报到、材料核验、招生宣讲"},{"label":"导师实验室营员接待活动","date":"2026-07-10T13:30:00.000Z","evidence":"7月10日13:30-17:00 导师实验室营员接待活动"}],"oneLine":"北京交通大学计算机学院面向2027届应届本科毕业生举办2026年暑期夏令营，7月6日18:00报名截止。","sourceUrl":"https://cs.bjtu.edu.cn/zsjy/yjszs3/yjszs_sszs/43d0504187d64309b1a97154f22a7e1d.htm"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('items','e04862b86ad08795000e2b5a3c7492c9','{"_id":"e04862b86ad08795000e2b5a3c7492c9","sourceId":"e04862b86ac1382a000398b37064a885","sourceName":"全国大学生信息安全竞赛 · 通知公告","canonicalUrl":"http://www.ciscn.cn/index.php/announcement/view/424","originalUrl":"http://www.ciscn.cn/index.php/announcement/view/424","title":"全国大学生信息安全竞赛官方网站","contentText":"由教育部高等学校网络空间安全专业教学指导委员会主办、山东大学承办的第十九届全国网络空间安全学科专业建设与人才培养研讨会，拟于2026年11月6日至8日在青岛召开。本次研讨会将为全国高等学校网络空间安全学科专业建设与人才培养搭建一个高水平交流平台，是在新形势下网络安全人才培养工作交流的一次盛会。研讨会聚焦新时代网络安全学科专业建设与人才培养，旨在构建合理、科学、系统的学科专业体系，培养一支政治过硬、技术过硬的网络空间安全人才队伍，推动网络空间安全教育高质量内涵式发展，为建设网络强国、维护国家网络安全提供支撑。会议将邀请中央网信办、教育部相关领导，全国一流网络安全学院、国内各大高校以及网络安全产业界的领导和专家参会，并安排了院士特邀报告、分论坛讨论等重点环节，分别从网络空间安全学科建设和人才培养、一流网安学院建设、网络安全领域“101计划”课程教材建设、产学研协同育人等方向探讨高校网络安全学科专业和院系建设，提高网络空间安全人才培养质量的途径和举措。现将会议有关事项通知如下：一、举办单位指导单位：中央网信办网络安全协调局教育部高等教育司主办单位：教育部高等学校网络空间安全专业教学指导委员会承办单位：山东大学网络空间安全学院密码与数字经济安全全国重点实验室二、时间、地点报到时间：2026年11月6日会议时间：2026年11月7日—8日（11月8日中午结束）会议地点：青岛市港中旅海泉湾皇冠假日酒店三、会议议程时间内容地点11月6日14:00-21:00会议报到酒店大堂19:00-21:00网络空间安全教指委委员工作会议雅典厅11月7日08:30-09:00开幕式锦绣宫09:00-12:00大会主论坛主旨报告锦绣宫14:00-17:30分论坛：1.人工智能时代网络安全人才培养创新论坛2.网络安全领域“101计划”课程及教材建设论坛雅典厅山东厅11月8日09:00-12:00分论坛：3.人工智能时代网络安全前沿技术与新型安全挑战论坛4.产学研协同育人与实战能力建设论坛雅典厅山东厅四、会议注册1.注册方式：填写基本信息注册后可生成“注册编号”，作为参会凭证。①访问会议网站进行注册https://cnsc2026.sincst.cn/②扫码注册： 2.注册费：1600元/人付款方式：银行汇款、扫码支付①银行汇款银行户名：青岛圣兮会务服务有限公司开 户 行：青岛农村商业银行股份有限公司蓝谷支行账      号：2060008904205000018380税      号：91370282MACL6H381E②扫码支付 请在银行汇款、微信支付附言中注明“注册编号”。注：会议期间提供工作餐，住宿费、交通费请自理。五、会议交通指南会议地点：青岛市港中旅海泉湾皇冠假日酒店酒店地址：山东省青岛市即墨区滨海公路188号酒店电话：0532-89068888六、会议联系人孙老师：13507016906郑老师：15621085775肖老师（财务）：18363931723    教育部高等学校网络空间安全专业教学指导委员会秘书长单位：北京邮电大学（代章）            2026年10月14日                        第十九届全国网络空间安全学科专业建设与人才培养研讨会会议通知.pdf","category":"competition","categories":["competition"],"status":"published","aiProcessing":"allow_ai","publishedAt":null,"discoveredAt":"2026-10-15T07:58:13.699Z","createdAt":"2026-10-15T07:58:13.699Z","updatedAt":"2026-10-15T07:58:22.341Z","summary":{"audience":["全国高等学校网络空间安全学科专业建设与人才培养相关人员","全国一流网络安全学院、国内各大高校领导与专家","网络安全产业界领导与专家"],"bullets":["主办单位为教育部高等学校网络空间安全专业教学指导委员会，承办单位为山东大学网络空间安全学院、密码与数字经济安全全国重点实验室。","会议报到时间为2026年11月6日，会议时间为2026年11月7日—8日（11月8日中午结束）。","会议地点为青岛市港中旅海泉湾皇冠假日酒店，地址为山东省青岛市即墨区滨海公路188号。","注册费1600元/人，可通过银行汇款或扫码支付，需在附言中注明“注册编号”。","会议期间提供工作餐，住宿费、交通费请自理。"],"keyDates":[],"oneLine":"第十九届全国网络空间安全学科专业建设与人才培养研讨会拟于2026年11月6日至8日在青岛召开。","sourceUrl":"http://www.ciscn.cn/index.php/announcement/view/424"}}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
INSERT INTO campus_documents(collection,id,body) VALUES('user_profiles','netlify_owner','{"_id":"netlify_owner","selectedSchoolId":"bjtu","webBookmarks":[]}'::jsonb) ON CONFLICT(collection,id) DO NOTHING;
